一、表关联关系配置1.1 需求分析需求： 查询员工信息并且把员工对应的部门信息一并查询出来。
部门和员工是 1 对 N 的关系（N-1：多个员工对应同一个部门）。
┌──────────┐       ┌──────────┐│  dept    │  1:N  │   emp    ││ 部门表    │──────→│  员工表   ││          │       │          ││ id       │       │ id       ││ name     │       │ name     ││          │       │ dept_id  │ ── 外键关联 dept.id└──────────┘       └──────────┘

1.2 创建实体类// ==================== 部门实体类 ====================package com.qiufenfen.entity;import lombok.Data;@Datapublic class Dept &#123;    private Integer id;    private String name;    // 双向关联时才需要：    // private List&lt;Emp&gt; empList;&#125;// ==================== 员工实体类 ====================package com.qiufenfen.entity;import lombok.Data;@Datapublic class Emp &#123;    private Integer id;    private String name;    private Double salary;    private Integer deptId;        // 关联部门（N 的一方配置对 1 的一方的引用）    private Dept dept;&#125;

1.3 单向关联 vs 双向关联单向关联（推荐）✓
在 N 的一方（Emp 类）配置对部门的引用。
// Emp 类中配置private Dept dept;  // 员工关联的部门// Dept 类中不配置员工集合

优点：

符合业务访问习惯：通常从员工查找部门，而非从部门遍历所有员工
避免数据冗余
查询效率高

双向关联
在 Dept 类中配置员工集合，同时在 Emp 类中配置部门引用。
// Emp 类中配置private Dept dept;// Dept 类中配置private List&lt;Emp&gt; empList;  // 部门下的所有员工

缺点：

容易导致循环引用
查询部门时可能不需要加载所有员工，浪费资源

1.4 数据库表结构-- 部门表CREATE TABLE dept (    id INT PRIMARY KEY AUTO_INCREMENT,    name VARCHAR(50) NOT NULL);-- 员工表CREATE TABLE emp (    id INT PRIMARY KEY AUTO_INCREMENT,    name VARCHAR(50) NOT NULL,    salary DECIMAL(10, 2),    dept_id INT,    FOREIGN KEY (dept_id) REFERENCES dept(id));


二、DAO 模式实现2.1 DAO 模式介绍DAO（Data Access Object）数据访问对象，将数据库访问操作封装在 DAO 层，实现业务逻辑与数据访问的分离。
┌─────────────┐│  Service 层  │  业务逻辑├─────────────┤│   DAO 层     │  数据访问（CRUD）├─────────────┤│  Database    │  数据库└─────────────┘

2.2 EmpDAO 接口package com.qiufenfen.dao;import com.qiufenfen.entity.Emp;import java.util.List;public interface EmpDAO &#123;        // 查询所有员工（带部门信息）    List&lt;Emp&gt; findAll();        // 根据 ID 查询员工（带部门信息）    Emp findById(Integer id);        // 添加员工    int insert(Emp emp);        // 更新员工    int update(Emp emp);        // 删除员工    int deleteById(Integer id);&#125;

2.3 EmpDAO 实现类package com.qiufenfen.dao.impl;import com.qiufenfen.dao.EmpDAO;import com.qiufenfen.entity.Dept;import com.qiufenfen.entity.Emp;import com.qiufenfen.util.DBUtil;import java.sql.*;import java.util.ArrayList;import java.util.List;public class EmpDAOImpl implements EmpDAO &#123;    // ============================================    // 方式1：两条 SQL 语句查询    // ============================================    @Override    public Emp findById(Integer id) &#123;        Connection conn = null;        PreparedStatement ps = null;        ResultSet rs = null;        Emp emp = null;        try &#123;            conn = DBUtil.getConnection();            // 第一步：查询员工信息            String sql = &quot;SELECT id, name, salary, dept_id FROM emp WHERE id = ?&quot;;            ps = conn.prepareStatement(sql);            ps.setInt(1, id);            rs = ps.executeQuery();            if (rs.next()) &#123;                emp = new Emp();                emp.setId(rs.getInt(&quot;id&quot;));                emp.setName(rs.getString(&quot;name&quot;));                emp.setSalary(rs.getDouble(&quot;salary&quot;));                emp.setDeptId(rs.getInt(&quot;dept_id&quot;));                // 第二步：查询部门信息                Integer deptId = rs.getInt(&quot;dept_id&quot;);                if (deptId != null) &#123;                    ps.close();                    String deptSql = &quot;SELECT id, name FROM dept WHERE id = ?&quot;;                    ps = conn.prepareStatement(deptSql);                    ps.setInt(1, deptId);                    ResultSet deptRs = ps.executeQuery();                    if (deptRs.next()) &#123;                        Dept dept = new Dept();                        dept.setId(deptRs.getInt(&quot;id&quot;));                        dept.setName(deptRs.getString(&quot;name&quot;));                        emp.setDept(dept);                    &#125;                &#125;            &#125;        &#125; catch (SQLException e) &#123;            e.printStackTrace();        &#125; finally &#123;            DBUtil.closeResource(rs, ps, conn);        &#125;        return emp;    &#125;    // ============================================    // 方式2：等值连接（推荐，一条 SQL）    // ============================================    @Override    public List&lt;Emp&gt; findAll() &#123;        Connection conn = null;        PreparedStatement ps = null;        ResultSet rs = null;        List&lt;Emp&gt; list = new ArrayList&lt;&gt;();        try &#123;            conn = DBUtil.getConnection();            // 等值连接查询（一条 SQL 搞定）            String sql = &quot;SELECT e.id AS emp_id, e.name AS emp_name, e.salary, &quot; +                         &quot;d.id AS dept_id, d.name AS dept_name &quot; +                         &quot;FROM emp e &quot; +                         &quot;INNER JOIN dept d ON e.dept_id = d.id&quot;;            ps = conn.prepareStatement(sql);            rs = ps.executeQuery();            while (rs.next()) &#123;                Emp emp = new Emp();                emp.setId(rs.getInt(&quot;emp_id&quot;));                emp.setName(rs.getString(&quot;emp_name&quot;));                emp.setSalary(rs.getDouble(&quot;salary&quot;));                // 封装部门信息                Dept dept = new Dept();                dept.setId(rs.getInt(&quot;dept_id&quot;));                dept.setName(rs.getString(&quot;dept_name&quot;));                emp.setDept(dept);                list.add(emp);            &#125;        &#125; catch (SQLException e) &#123;            e.printStackTrace();        &#125; finally &#123;            DBUtil.closeResource(rs, ps, conn);        &#125;        return list;    &#125;    @Override    public int insert(Emp emp) &#123;        Connection conn = null;        PreparedStatement ps = null;        int rows = 0;        try &#123;            conn = DBUtil.getConnection();            String sql = &quot;INSERT INTO emp(name, salary, dept_id) VALUES(?, ?, ?)&quot;;            ps = conn.prepareStatement(sql);            ps.setString(1, emp.getName());            ps.setDouble(2, emp.getSalary());            ps.setInt(3, emp.getDeptId());            rows = ps.executeUpdate();        &#125; catch (SQLException e) &#123;            e.printStackTrace();        &#125; finally &#123;            DBUtil.closeResource(null, ps, conn);        &#125;        return rows;    &#125;    @Override    public int update(Emp emp) &#123;        Connection conn = null;        PreparedStatement ps = null;        int rows = 0;        try &#123;            conn = DBUtil.getConnection();            String sql = &quot;UPDATE emp SET name = ?, salary = ?, dept_id = ? WHERE id = ?&quot;;            ps = conn.prepareStatement(sql);            ps.setString(1, emp.getName());            ps.setDouble(2, emp.getSalary());            ps.setInt(3, emp.getDeptId());            ps.setInt(4, emp.getId());            rows = ps.executeUpdate();        &#125; catch (SQLException e) &#123;            e.printStackTrace();        &#125; finally &#123;            DBUtil.closeResource(null, ps, conn);        &#125;        return rows;    &#125;    @Override    public int deleteById(Integer id) &#123;        Connection conn = null;        PreparedStatement ps = null;        int rows = 0;        try &#123;            conn = DBUtil.getConnection();            String sql = &quot;DELETE FROM emp WHERE id = ?&quot;;            ps = conn.prepareStatement(sql);            ps.setInt(1, id);            rows = ps.executeUpdate();        &#125; catch (SQLException e) &#123;            e.printStackTrace();        &#125; finally &#123;            DBUtil.closeResource(null, ps, conn);        &#125;        return rows;    &#125;&#125;

2.4 单元测试package com.qiufenfen.test;import com.qiufenfen.dao.EmpDAO;import com.qiufenfen.dao.impl.EmpDAOImpl;import com.qiufenfen.entity.Emp;import org.junit.jupiter.api.Test;import java.util.List;public class EmpDAOTest &#123;    private EmpDAO empDAO = new EmpDAOImpl();    @Test    public void testFindById() &#123;        Emp emp = empDAO.findById(1);        if (emp != null) &#123;            System.out.println(&quot;员工：&quot; + emp.getName() +                 &quot;，薪资：&quot; + emp.getSalary() +                 &quot;，部门：&quot; + emp.getDept().getName());        &#125;    &#125;    @Test    public void testFindAll() &#123;        List&lt;Emp&gt; list = empDAO.findAll();        for (Emp emp : list) &#123;            System.out.println(&quot;员工：&quot; + emp.getName() +                 &quot;，部门：&quot; + emp.getDept().getName());        &#125;    &#125;    @Test    public void testInsert() &#123;        Emp emp = new Emp();        emp.setName(&quot;赵六&quot;);        emp.setSalary(8500);        emp.setDeptId(1);        int rows = empDAO.insert(emp);        System.out.println(&quot;插入了 &quot; + rows + &quot; 行&quot;);    &#125;    @Test    public void testUpdate() &#123;        Emp emp = new Emp();        emp.setId(1);        emp.setName(&quot;张三（已更新）&quot;);        emp.setSalary(10000);        emp.setDeptId(2);        int rows = empDAO.update(emp);        System.out.println(&quot;更新了 &quot; + rows + &quot; 行&quot;);    &#125;    @Test    public void testDelete() &#123;        int rows = empDAO.deleteById(10);        System.out.println(&quot;删除了 &quot; + rows + &quot; 行&quot;);    &#125;&#125;


三、项目实战：学生管理系统3.1 数据库设计-- 创建数据库CREATE DATABASE IF NOT EXISTS student_db    CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;USE student_db;-- ============================-- 班级表（1 方）-- ============================CREATE TABLE tb_clazz (    clazzId INT PRIMARY KEY AUTO_INCREMENT,    clazzName VARCHAR(30) NOT NULL COMMENT &#x27;班级名称&#x27;);INSERT INTO tb_clazz (clazzName) VALUES (&#x27;Java一班&#x27;), (&#x27;Java二班&#x27;), (&#x27;Python一班&#x27;);-- ============================-- 学生表（N 方）-- ============================CREATE TABLE tb_stu (    stuNo VARCHAR(10) PRIMARY KEY COMMENT &#x27;学号&#x27;,    stuName VARCHAR(20) NOT NULL COMMENT &#x27;姓名&#x27;,    stuInDate DATE COMMENT &#x27;入学时间&#x27;,    stuBirth DATE COMMENT &#x27;生日&#x27;,    stuSex CHAR(2) DEFAULT &#x27;男&#x27; COMMENT &#x27;性别&#x27;,    clazz_id INT COMMENT &#x27;班级ID（外键）&#x27;);-- 建立外键关联ALTER TABLE tb_stu ADD CONSTRAINT fk_stu_clazz    FOREIGN KEY (clazz_id) REFERENCES tb_clazz(clazzId);-- ============================-- 插入学生数据-- ============================INSERT INTO tb_stu VALUES(&#x27;0509301-01&#x27;, &#x27;张三&#x27;, &#x27;2022-09-01&#x27;, &#x27;1999-09-09&#x27;, &#x27;男&#x27;, 1),(&#x27;0509301-02&#x27;, &#x27;李四&#x27;, &#x27;2022-09-01&#x27;, &#x27;2000-01-09&#x27;, &#x27;女&#x27;, 1),(&#x27;0509301-03&#x27;, &#x27;王五&#x27;, &#x27;2022-09-01&#x27;, &#x27;2001-02-02&#x27;, &#x27;男&#x27;, 1),(&#x27;0509301-04&#x27;, &#x27;赵六&#x27;, &#x27;2022-09-01&#x27;, &#x27;1998-08-09&#x27;, &#x27;男&#x27;, 1),(&#x27;0509302-01&#x27;, &#x27;jack&#x27;, &#x27;2022-09-01&#x27;, &#x27;1999-09-09&#x27;, &#x27;男&#x27;, 2),(&#x27;0509302-02&#x27;, &#x27;tom&#x27;, &#x27;2022-09-01&#x27;, &#x27;2000-01-09&#x27;, &#x27;女&#x27;, 2),(&#x27;0509302-03&#x27;, &#x27;rose&#x27;, &#x27;2022-09-01&#x27;, &#x27;2001-02-02&#x27;, &#x27;男&#x27;, 2),(&#x27;0509302-04&#x27;, &#x27;lili&#x27;, &#x27;2022-09-01&#x27;, &#x27;1998-08-09&#x27;, &#x27;男&#x27;, 2),(&#x27;0509303-01&#x27;, &#x27;jdbc&#x27;, &#x27;2022-09-01&#x27;, &#x27;1999-09-09&#x27;, &#x27;男&#x27;, 3),(&#x27;0509303-02&#x27;, &#x27;mysql&#x27;, &#x27;2022-09-01&#x27;, &#x27;2000-01-09&#x27;, &#x27;女&#x27;, 3);

3.2 项目结构student-system/├── src/│   ├── main/│   │   ├── java/│   │   │   └── com/qiufenfen/│   │   │       ├── entity/│   │   │       │   ├── Clazz.java│   │   │       │   └── Student.java│   │   │       ├── dao/│   │   │       │   ├── ClazzDAO.java│   │   │       │   ├── StudentDAO.java│   │   │       │   └── impl/│   │   │       │       ├── ClazzDAOImpl.java│   │   │       │       └── StudentDAOImpl.java│   │   │       ├── service/│   │   │       │   ├── StudentService.java│   │   │       │   └── impl/│   │   │       │       └── StudentServiceImpl.java│   │   │       ├── util/│   │   │       │   ├── DBUtil.java│   │   │       │   └── PageUtil.java│   │   │       └── Main.java│   │   └── resources/│   │       └── jdbc.properties│   └── test/│       └── java/│           └── com/qiufenfen/test/│               └── StudentDAOTest.java└── pom.xml

3.3 实体类// ==================== Clazz.java ====================package com.qiufenfen.entity;import lombok.Data;@Datapublic class Clazz &#123;    private Integer clazzId;    private String clazzName;&#125;// ==================== Student.java ====================package com.qiufenfen.entity;import lombok.Data;import java.util.Date;@Datapublic class Student &#123;    private String stuNo;      // 学号（主键）    private String stuName;    // 姓名    private Date stuInDate;    // 入学时间    private Date stuBirth;     // 生日    private String stuSex;     // 性别    private Integer clazzId;   // 班级ID        // 关联班级（单向关联）    private Clazz clazz;&#125;

3.4 StudentDAO 接口与实现// ==================== StudentDAO 接口 ====================package com.qiufenfen.dao;import com.qiufenfen.entity.Student;import com.qiufenfen.util.PageUtil;import java.util.List;public interface StudentDAO &#123;    // 分页查询学生（带班级信息）    PageUtil&lt;Student&gt; findByPage(int pageNum, int pageSize);        // 根据学号查询学生    Student findByStuNo(String stuNo);        // 添加学生    int insert(Student stu);        // 更新学生    int update(Student stu);        // 删除学生    int deleteByStuNo(String stuNo);        // 查询总记录数    long count();&#125;// ==================== StudentDAOImpl 实现类 ====================package com.qiufenfen.dao.impl;import com.qiufenfen.dao.StudentDAO;import com.qiufenfen.entity.Clazz;import com.qiufenfen.entity.Student;import com.qiufenfen.util.DBUtil;import com.qiufenfen.util.PageUtil;import java.sql.*;import java.util.ArrayList;import java.util.List;public class StudentDAOImpl implements StudentDAO &#123;    @Override    public PageUtil&lt;Student&gt; findByPage(int pageNum, int pageSize) &#123;        PageUtil&lt;Student&gt; page = new PageUtil&lt;&gt;(pageNum, pageSize);        Connection conn = null;        PreparedStatement ps = null;        ResultSet rs = null;        List&lt;Student&gt; list = new ArrayList&lt;&gt;();        try &#123;            conn = DBUtil.getConnection();            // 1. 查询总记录数            String countSql = &quot;SELECT COUNT(*) FROM tb_stu&quot;;            ps = conn.prepareStatement(countSql);            rs = ps.executeQuery();            if (rs.next()) &#123;                page.setTotalRecords(rs.getLong(1));            &#125;            // 2. 查询当前页数据（等值连接带班级信息）            String sql = &quot;SELECT s.*, c.clazzName &quot; +                         &quot;FROM tb_stu s &quot; +                         &quot;INNER JOIN tb_clazz c ON s.clazz_id = c.clazzId &quot; +                         &quot;LIMIT ?, ?&quot;;            ps = conn.prepareStatement(sql);            ps.setInt(1, page.getOffset());            ps.setInt(2, page.getPageSize());            rs = ps.executeQuery();            while (rs.next()) &#123;                Student stu = new Student();                stu.setStuNo(rs.getString(&quot;stuNo&quot;));                stu.setStuName(rs.getString(&quot;stuName&quot;));                stu.setStuInDate(rs.getDate(&quot;stuInDate&quot;));                stu.setStuBirth(rs.getDate(&quot;stuBirth&quot;));                stu.setStuSex(rs.getString(&quot;stuSex&quot;));                stu.setClazzId(rs.getInt(&quot;clazz_id&quot;));                // 封装班级信息                Clazz clazz = new Clazz();                clazz.setClazzId(rs.getInt(&quot;clazz_id&quot;));                clazz.setClazzName(rs.getString(&quot;clazzName&quot;));                stu.setClazz(clazz);                list.add(stu);            &#125;            page.setData(list);        &#125; catch (SQLException e) &#123;            e.printStackTrace();        &#125; finally &#123;            DBUtil.closeResource(rs, ps, conn);        &#125;        return page;    &#125;    @Override    public Student findByStuNo(String stuNo) &#123;        Connection conn = null;        PreparedStatement ps = null;        ResultSet rs = null;        Student stu = null;        try &#123;            conn = DBUtil.getConnection();            String sql = &quot;SELECT s.*, c.clazzName &quot; +                         &quot;FROM tb_stu s &quot; +                         &quot;INNER JOIN tb_clazz c ON s.clazz_id = c.clazzId &quot; +                         &quot;WHERE s.stuNo = ?&quot;;            ps = conn.prepareStatement(sql);            ps.setString(1, stuNo);            rs = ps.executeQuery();            if (rs.next()) &#123;                stu = new Student();                stu.setStuNo(rs.getString(&quot;stuNo&quot;));                stu.setStuName(rs.getString(&quot;stuName&quot;));                stu.setStuInDate(rs.getDate(&quot;stuInDate&quot;));                stu.setStuBirth(rs.getDate(&quot;stuBirth&quot;));                stu.setStuSex(rs.getString(&quot;stuSex&quot;));                stu.setClazzId(rs.getInt(&quot;clazz_id&quot;));                Clazz clazz = new Clazz();                clazz.setClazzId(rs.getInt(&quot;clazz_id&quot;));                clazz.setClazzName(rs.getString(&quot;clazzName&quot;));                stu.setClazz(clazz);            &#125;        &#125; catch (SQLException e) &#123;            e.printStackTrace();        &#125; finally &#123;            DBUtil.closeResource(rs, ps, conn);        &#125;        return stu;    &#125;    @Override    public int insert(Student stu) &#123;        Connection conn = null;        PreparedStatement ps = null;        int rows = 0;        try &#123;            conn = DBUtil.getConnection();            String sql = &quot;INSERT INTO tb_stu(stuNo, stuName, stuInDate, stuBirth, stuSex, clazz_id) &quot; +                         &quot;VALUES(?, ?, ?, ?, ?, ?)&quot;;            ps = conn.prepareStatement(sql);            ps.setString(1, stu.getStuNo());            ps.setString(2, stu.getStuName());            ps.setDate(3, new java.sql.Date(stu.getStuInDate().getTime()));            ps.setDate(4, new java.sql.Date(stu.getStuBirth().getTime()));            ps.setString(5, stu.getStuSex());            ps.setInt(6, stu.getClazzId());            rows = ps.executeUpdate();        &#125; catch (SQLException e) &#123;            e.printStackTrace();        &#125; finally &#123;            DBUtil.closeResource(null, ps, conn);        &#125;        return rows;    &#125;    @Override    public int update(Student stu) &#123;        Connection conn = null;        PreparedStatement ps = null;        int rows = 0;        try &#123;            conn = DBUtil.getConnection();            String sql = &quot;UPDATE tb_stu SET stuName=?, stuInDate=?, stuBirth=?, stuSex=?, clazz_id=? &quot; +                         &quot;WHERE stuNo=?&quot;;            ps = conn.prepareStatement(sql);            ps.setString(1, stu.getStuName());            ps.setDate(2, new java.sql.Date(stu.getStuInDate().getTime()));            ps.setDate(3, new java.sql.Date(stu.getStuBirth().getTime()));            ps.setString(4, stu.getStuSex());            ps.setInt(5, stu.getClazzId());            ps.setString(6, stu.getStuNo());            rows = ps.executeUpdate();        &#125; catch (SQLException e) &#123;            e.printStackTrace();        &#125; finally &#123;            DBUtil.closeResource(null, ps, conn);        &#125;        return rows;    &#125;    @Override    public int deleteByStuNo(String stuNo) &#123;        Connection conn = null;        PreparedStatement ps = null;        int rows = 0;        try &#123;            conn = DBUtil.getConnection();            String sql = &quot;DELETE FROM tb_stu WHERE stuNo = ?&quot;;            ps = conn.prepareStatement(sql);            ps.setString(1, stuNo);            rows = ps.executeUpdate();        &#125; catch (SQLException e) &#123;            e.printStackTrace();        &#125; finally &#123;            DBUtil.closeResource(null, ps, conn);        &#125;        return rows;    &#125;    @Override    public long count() &#123;        Connection conn = null;        PreparedStatement ps = null;        ResultSet rs = null;        long count = 0;        try &#123;            conn = DBUtil.getConnection();            String sql = &quot;SELECT COUNT(*) FROM tb_stu&quot;;            ps = conn.prepareStatement(sql);            rs = ps.executeQuery();            if (rs.next()) &#123;                count = rs.getLong(1);            &#125;        &#125; catch (SQLException e) &#123;            e.printStackTrace();        &#125; finally &#123;            DBUtil.closeResource(rs, ps, conn);        &#125;        return count;    &#125;&#125;

3.5 Service 层// ==================== StudentService 接口 ====================package com.qiufenfen.service;import com.qiufenfen.entity.Student;import com.qiufenfen.util.PageUtil;public interface StudentService &#123;    PageUtil&lt;Student&gt; findByPage(int pageNum, int pageSize);    Student findByStuNo(String stuNo);    boolean addStudent(Student stu);    boolean updateStudent(Student stu);    boolean deleteStudent(String stuNo);&#125;// ==================== StudentServiceImpl 实现类 ====================package com.qiufenfen.service.impl;import com.qiufenfen.dao.StudentDAO;import com.qiufenfen.dao.impl.StudentDAOImpl;import com.qiufenfen.entity.Student;import com.qiufenfen.service.StudentService;import com.qiufenfen.util.PageUtil;public class StudentServiceImpl implements StudentService &#123;    private StudentDAO studentDAO = new StudentDAOImpl();    @Override    public PageUtil&lt;Student&gt; findByPage(int pageNum, int pageSize) &#123;        return studentDAO.findByPage(pageNum, pageSize);    &#125;    @Override    public Student findByStuNo(String stuNo) &#123;        return studentDAO.findByStuNo(stuNo);    &#125;    @Override    public boolean addStudent(Student stu) &#123;        // 业务校验：学号不能重复        Student existing = studentDAO.findByStuNo(stu.getStuNo());        if (existing != null) &#123;            throw new RuntimeException(&quot;学号已存在&quot;);        &#125;        return studentDAO.insert(stu) &gt; 0;    &#125;    @Override    public boolean updateStudent(Student stu) &#123;        return studentDAO.update(stu) &gt; 0;    &#125;    @Override    public boolean deleteStudent(String stuNo) &#123;        return studentDAO.deleteByStuNo(stuNo) &gt; 0;    &#125;&#125;

