;);            stu.setStuBirth(new SimpleDateFormat(&quot;yyyy-MM-dd&quot;).parse(scanner.nextLine()));            System.out.print(&quot;班级ID：&quot;);            stu.setClazzId(scanner.nextInt());            scanner.nextLine();            if (studentService.addStudent(stu)) &#123;                System.out.println(&quot;添加成功！&quot;);            &#125; else &#123;                System.out.println(&quot;添加失败！&quot;);            &#125;        &#125; catch (Exception e) &#123;            System.out.println(&quot;输入格式错误：&quot; + e.getMessage());        &#125;    &#125;    // 修改学生    private static void updateStudent() &#123;        System.out.print(&quot;请输入要修改的学号：&quot;);        String stuNo = scanner.nextLine();        Student stu = studentService.findByStuNo(stuNo);        if (stu == null) &#123;            System.out.println(&quot;未找到学生！&quot;);            return;        &#125;        System.out.print(&quot;姓名（&quot; + stu.getStuName() + &quot;）：&quot;);        String name = scanner.nextLine();        if (!name.isEmpty()) stu.setStuName(name);        System.out.print(&quot;性别（&quot; + stu.getStuSex() + &quot;）：&quot;);        String sex = scanner.nextLine();        if (!sex.isEmpty()) stu.setStuSex(sex);        if (studentService.updateStudent(stu)) &#123;            System.out.println(&quot;修改成功！&quot;);        &#125; else &#123;            System.out.println(&quot;修改失败！&quot;);        &#125;    &#125;    // 删除学生    private static void deleteStudent() &#123;        System.out.print(&quot;请输入要删除的学号：&quot;);        String stuNo = scanner.nextLine();        if (studentService.deleteStudent(stuNo)) &#123;            System.out.println(&quot;删除成功！&quot;);        &#125; else &#123;            System.out.println(&quot;删除失败！&quot;);        &#125;    &#125;&#125;



💡 小结：本章通过两个实战案例巩固 JDBC 知识。首先讲解了表关联关系配置（单向关联 vs 双向关联），推荐在 N 的一方配置单向关联。然后通过 DAO 模式实现了员工管理的完整 CRUD，对比了两种查询方式（两条 SQL vs 等值连接）。最后通过学生管理系统项目，展示了从数据库设计、实体类、DAO 层、Service 层到控制台主程序的完整开发流程。

一、Express 简介1.1 框架特点Express 是 Node.js 平台上最流行、最成熟的 Web 应用框架，具有以下特点：



