二、路由系统2.1 路由方法Express 支持所有 HTTP 请求方法：
// app.jsconst express = require(&#x27;express&#x27;);const app = express();// GET 请求app.get(&#x27;/users&#x27;, (req, res) =&gt; &#123;  res.json(&#123; method: &#x27;GET&#x27;, message: &#x27;获取用户列表&#x27; &#125;);&#125;);// POST 请求app.post(&#x27;/users&#x27;, (req, res) =&gt; &#123;  res.json(&#123; method: &#x27;POST&#x27;, message: &#x27;创建用户&#x27; &#125;);&#125;);// PUT 请求（完整更新）app.put(&#x27;/users/:id&#x27;, (req, res) =&gt; &#123;  res.json(&#123; method: &#x27;PUT&#x27;, message: `更新用户 $&#123;req.params.id&#125;` &#125;);&#125;);// PATCH 请求（部分更新）app.patch(&#x27;/users/:id&#x27;, (req, res) =&gt; &#123;  res.json(&#123; method: &#x27;PATCH&#x27;, message: `部分更新用户 $&#123;req.params.id&#125;` &#125;);&#125;);// DELETE 请求app.delete(&#x27;/users/:id&#x27;, (req, res) =&gt; &#123;  res.json(&#123; method: &#x27;DELETE&#x27;, message: `删除用户 $&#123;req.params.id&#125;` &#125;);&#125;);// 匹配所有 HTTP 方法app.all(&#x27;/health&#x27;, (req, res) =&gt; &#123;  res.json(&#123; status: &#x27;ok&#x27;, timestamp: new Date().toISOString() &#125;);&#125;);app.listen(3000);

2.2 路由参数路径参数（Route Params）// 单个参数app.get(&#x27;/users/:id&#x27;, (req, res) =&gt; &#123;  console.log(req.params); // &#123; id: &#x27;123&#x27; &#125;  res.json(&#123; userId: req.params.id &#125;);&#125;);// 多个参数app.get(&#x27;/posts/:postId/comments/:commentId&#x27;, (req, res) =&gt; &#123;  console.log(req.params); // &#123; postId: &#x27;1&#x27;, commentId: &#x27;2&#x27; &#125;  res.json(req.params);&#125;);// 可选参数（使用正则）app.get(&#x27;/books/:id?&#x27;, (req, res) =&gt; &#123;  if (req.params.id) &#123;    res.json(&#123; bookId: req.params.id &#125;);  &#125; else &#123;    res.json(&#123; books: [] &#125;);  &#125;&#125;);

查询参数（Query String）// GET /search?keyword=nodejs&amp;page=1&amp;limit=10app.get(&#x27;/search&#x27;, (req, res) =&gt; &#123;  console.log(req.query);  // &#123; keyword: &#x27;nodejs&#x27;, page: &#x27;1&#x27;, limit: &#x27;10&#x27; &#125;  const &#123; keyword, page = 1, limit = 10 &#125; = req.query;  res.json(&#123;    keyword,    page: parseInt(page),    limit: parseInt(limit),    results: []  &#125;);&#125;);

2.3 路由模块化使用 express.Router 实现路由模块化：
// routes/users.jsconst express = require(&#x27;express&#x27;);const router = express.Router();// 用户列表router.get(&#x27;/&#x27;, (req, res) =&gt; &#123;  res.json(&#123; users: [] &#125;);&#125;);// 创建用户router.post(&#x27;/&#x27;, (req, res) =&gt; &#123;  res.json(&#123; message: &#x27;用户创建成功&#x27; &#125;);&#125;);// 获取单个用户router.get(&#x27;/:id&#x27;, (req, res) =&gt; &#123;  res.json(&#123; userId: req.params.id &#125;);&#125;);// 更新用户router.put(&#x27;/:id&#x27;, (req, res) =&gt; &#123;  res.json(&#123; message: `用户 $&#123;req.params.id&#125; 更新成功` &#125;);&#125;);// 删除用户router.delete(&#x27;/:id&#x27;, (req, res) =&gt; &#123;  res.json(&#123; message: `用户 $&#123;req.params.id&#125; 删除成功` &#125;);&#125;);module.exports = router;

// app.jsconst express = require(&#x27;express&#x27;);const usersRouter = require(&#x27;./routes/users&#x27;);const app = express();// 挂载路由app.use(&#x27;/users&#x27;, usersRouter);app.listen(3000);

三、中间件3.1 中间件概念中间件（Middleware）是 Express 的核心机制，它是一个函数，可以访问请求对象（req）、响应对象（res）和 next 函数。
请求 ──▶ 中间件1 ──▶ 中间件2 ──▶ ... ──▶ 路由处理 ──▶ 响应              │              ▼            next()

3.2 应用级中间件const express = require(&#x27;express&#x27;);const app = express();// 记录请求日志app.use((req, res, next) =&gt; &#123;  const start = Date.now();  console.log(`$&#123;req.method&#125; $&#123;req.url&#125; - $&#123;new Date().toISOString()&#125;`);  // 调用 next() 继续执行下一个中间件  next();  const duration = Date.now() - start;  console.log(`请求耗时: $&#123;duration&#125;ms`);&#125;);// 只对特定路径生效app.use(&#x27;/api&#x27;, (req, res, next) =&gt; &#123;  console.log(&#x27;API 请求拦截&#x27;);  next();&#125;);app.get(&#x27;/&#x27;, (req, res) =&gt; &#123;  res.send(&#x27;Home Page&#x27;);&#125;);app.get(&#x27;/api/data&#x27;, (req, res) =&gt; &#123;  res.json(&#123; data: &#x27;api data&#x27; &#125;);&#125;);app.listen(3000);

3.3 路由级中间件// 只对特定路由生效的中间件const checkAuth = (req, res, next) =&gt; &#123;  const token = req.headers[&#x27;authorization&#x27;];  if (!token) &#123;    return res.status(401).json(&#123; error: &#x27;未提供认证令牌&#x27; &#125;);  &#125;  // 验证 token...  req.userId = &#x27;user123&#x27;; // 将用户信息挂载到 req  next();&#125;;// 应用到单个路由app.get(&#x27;/profile&#x27;, checkAuth, (req, res) =&gt; &#123;  res.json(&#123; userId: req.userId, name: &#x27;张三&#x27; &#125;);&#125;);// 应用到路由组app.get(&#x27;/settings&#x27;, checkAuth, (req, res) =&gt; &#123;  res.json(&#123; userId: req.userId, theme: &#x27;dark&#x27; &#125;);&#125;);

3.4 错误处理中间件// 错误处理中间件（必须注册在所有路由之后）app.use((err, req, res, next) =&gt; &#123;  console.error(&#x27;错误:&#x27;, err.message);  // 区分不同类型的错误  if (err.name === &#x27;ValidationError&#x27;) &#123;    return res.status(400).json(&#123; error: &#x27;参数验证失败&#x27;, details: err.message &#125;);  &#125;  if (err.name === &#x27;UnauthorizedError&#x27;) &#123;    return res.status(401).json(&#123; error: &#x27;认证失败&#x27; &#125;);  &#125;  // 未知错误  res.status(500).json(&#123; error: &#x27;服务器内部错误&#x27; &#125;);&#125;);

