一、创建 Vue 应用1.1 使用 createAppVue 3 使用 createApp 创建应用实例：
// main.jsimport &#123; createApp &#125; from &#x27;vue&#x27;import App from &#x27;./App.vue&#x27;const app = createApp(App)app.mount(&#x27;#app&#x27;)

1.2 应用配置const app = createApp(App)// 全局配置app.config.errorHandler = (err) =&gt; &#123;  console.error(&#x27;全局错误:&#x27;, err)&#125;// 注册全局组件app.component(&#x27;GlobalButton&#x27;, &#123;  template: &#x27;&lt;button&gt;全局按钮&lt;/button&gt;&#x27;&#125;)// 注册全局指令app.directive(&#x27;focus&#x27;, &#123;  mounted(el) &#123;    el.focus()  &#125;&#125;)// 提供全局属性app.provide(&#x27;globalMessage&#x27;, &#x27;全局消息&#x27;)app.mount(&#x27;#app&#x27;)

1.3 实战案例：创建一个简单计数器&lt;!-- Counter.vue --&gt;&lt;template&gt;  &lt;div class=&quot;counter&quot;&gt;    &lt;h2&gt;计数器&lt;/h2&gt;    &lt;p&gt;当前值: &#123;&#123; count &#125;&#125;&lt;/p&gt;    &lt;div class=&quot;buttons&quot;&gt;      &lt;button @click=&quot;decrement&quot;&gt;-&lt;/button&gt;      &lt;button @click=&quot;reset&quot;&gt;重置&lt;/button&gt;      &lt;button @click=&quot;increment&quot;&gt;+&lt;/button&gt;    &lt;/div&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref &#125; from &#x27;vue&#x27;const count = ref(0)function increment() &#123;  count.value++&#125;function decrement() &#123;  count.value--&#125;function reset() &#123;  count.value = 0&#125;&lt;/script&gt;&lt;style scoped&gt;.counter &#123;  text-align: center;  padding: 20px;&#125;.buttons button &#123;  margin: 5px;  padding: 8px 16px;&#125;&lt;/style&gt;


二、模板语法2.1 文本插值&lt;template&gt;  &lt;!-- 双大括号语法 --&gt;  &lt;p&gt;&#123;&#123; message &#125;&#125;&lt;/p&gt;  &lt;!-- 支持 JavaScript 表达式 --&gt;  &lt;p&gt;&#123;&#123; number + 1 &#125;&#125;&lt;/p&gt;  &lt;p&gt;&#123;&#123; ok ? &#x27;YES&#x27; : &#x27;NO&#x27; &#125;&#125;&lt;/p&gt;  &lt;p&gt;&#123;&#123; message.split(&#x27;&#x27;).reverse().join(&#x27;&#x27;) &#125;&#125;&lt;/p&gt;&lt;/template&gt;&lt;script setup&gt;const message = &#x27;Hello Vue 3!&#x27;const number = 10const ok = true&lt;/script&gt;

2.2 原始 HTML&lt;template&gt;  &lt;!-- 使用 v-html 渲染原始 HTML --&gt;  &lt;div v-html=&quot;rawHtml&quot;&gt;&lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;const rawHtml = &#x27;&lt;strong style=&quot;color: red;&quot;&gt;红色粗体文字&lt;/strong&gt;&#x27;&lt;/script&gt;


⚠️ 安全警告：在网站上动态渲染任意 HTML 是非常危险的，容易导致 XSS 攻击。只对可信内容使用 HTML 插值。

2.3 属性绑定&lt;template&gt;  &lt;!-- 动态绑定属性 --&gt;  &lt;div v-bind:id=&quot;dynamicId&quot;&gt;&lt;/div&gt;  &lt;button :disabled=&quot;isDisabled&quot;&gt;按钮&lt;/button&gt;  &lt;!-- 绑定多个属性 --&gt;  &lt;input v-bind=&quot;objectOfAttrs&quot;&gt;  &lt;!-- 动态属性名 --&gt;  &lt;button :[attributeName]=&quot;value&quot;&gt;动态属性&lt;/button&gt;&lt;/template&gt;&lt;script setup&gt;const dynamicId = &#x27;my-id&#x27;const isDisabled = trueconst objectOfAttrs = &#123;  id: &#x27;container&#x27;,  class: &#x27;wrapper&#x27;,  style: &#x27;color: blue;&#x27;&#125;const attributeName = &#x27;title&#x27;const value = &#x27;提示文本&#x27;&lt;/script&gt;

2.4 实战案例：动态样式卡片&lt;template&gt;  &lt;div class=&quot;card&quot; :style=&quot;cardStyle&quot;&gt;    &lt;h3&gt;&#123;&#123; title &#125;&#125;&lt;/h3&gt;    &lt;p&gt;&#123;&#123; content &#125;&#125;&lt;/p&gt;    &lt;button @click=&quot;changeTheme&quot;&gt;切换主题&lt;/button&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref, computed &#125; from &#x27;vue&#x27;const title = ref(&#x27;动态卡片&#x27;)const content = ref(&#x27;这是一个可以动态切换主题的卡片组件&#x27;)const themeIndex = ref(0)const themes = [  &#123; bg: &#x27;#fff&#x27;, color: &#x27;#333&#x27;, border: &#x27;#ddd&#x27; &#125;,  &#123; bg: &#x27;#2c3e50&#x27;, color: &#x27;#fff&#x27;, border: &#x27;#42b983&#x27; &#125;,  &#123; bg: &#x27;#f39c12&#x27;, color: &#x27;#fff&#x27;, border: &#x27;#e67e22&#x27; &#125;]const cardStyle = computed(() =&gt; &#123;  const theme = themes[themeIndex.value]  return &#123;    backgroundColor: theme.bg,    color: theme.color,    border: `2px solid $&#123;theme.border&#125;`  &#125;&#125;)function changeTheme() &#123;  themeIndex.value = (themeIndex.value + 1) % themes.length&#125;&lt;/script&gt;&lt;style scoped&gt;.card &#123;  padding: 20px;  border-radius: 8px;  max-width: 300px;  transition: all 0.3s ease;&#125;.card button &#123;  margin-top: 10px;  padding: 8px 16px;  cursor: pointer;&#125;&lt;/style&gt;


三、响应式数据3.1 ref 基础ref 用于创建响应式数据：
&lt;template&gt;  &lt;p&gt;&#123;&#123; message &#125;&#125;&lt;/p&gt;  &lt;button @click=&quot;updateMessage&quot;&gt;修改消息&lt;/button&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref &#125; from &#x27;vue&#x27;// 创建响应式引用const message = ref(&#x27;Hello!&#x27;)// 在 script 中需要使用 .value 访问function updateMessage() &#123;  message.value = &#x27;Updated!&#x27;&#125;console.log(message.value) // &#x27;Hello!&#x27;&lt;/script&gt;

3.2 reactive 对象reactive 用于创建响应式对象：
&lt;template&gt;  &lt;p&gt;姓名: &#123;&#123; user.name &#125;&#125;&lt;/p&gt;  &lt;p&gt;年龄: &#123;&#123; user.age &#125;&#125;&lt;/p&gt;  &lt;button @click=&quot;growUp&quot;&gt;长大一岁&lt;/button&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; reactive &#125; from &#x27;vue&#x27;// 创建响应式对象const user = reactive(&#123;  name: &#x27;张三&#x27;,  age: 25,  profile: &#123;    email: &#x27;zhangsan@example.com&#x27;  &#125;&#125;)function growUp() &#123;  user.age++ // 直接访问属性，不需要 .value&#125;console.log(user.age) // 25&lt;/script&gt;

