&lt;script setup&gt;import &#123; ref, reactive &#125; from &#x27;vue&#x27;// ref 示例const count = ref(0)const user = ref(&#123; name: &#x27;张三&#x27; &#125;)// 可以整体替换user.value = &#123; name: &#x27;李四&#x27; &#125;// reactive 示例const state = reactive(&#123;  count: 0,  user: &#123; name: &#x27;张三&#x27; &#125;&#125;)// 不能整体替换，但可以修改属性state.count++state.user.name = &#x27;李四&#x27;// 解构会丢失响应式const &#123; count: reactiveCount &#125; = state // 不是响应式！&lt;/script&gt;

3.4 实战案例：购物车&lt;template&gt;  &lt;div class=&quot;cart&quot;&gt;    &lt;h2&gt;购物车&lt;/h2&gt;    &lt;!-- 商品列表 --&gt;    &lt;div class=&quot;product-list&quot;&gt;      &lt;div v-for=&quot;item in cart.items&quot; :key=&quot;item.id&quot; class=&quot;product-item&quot;&gt;        &lt;span&gt;&#123;&#123; item.name &#125;&#125;&lt;/span&gt;        &lt;span&gt;¥&#123;&#123; item.price &#125;&#125;&lt;/span&gt;        &lt;div class=&quot;quantity&quot;&gt;          &lt;button @click=&quot;decreaseQuantity(item)&quot;&gt;-&lt;/button&gt;          &lt;span&gt;&#123;&#123; item.quantity &#125;&#125;&lt;/span&gt;          &lt;button @click=&quot;increaseQuantity(item)&quot;&gt;+&lt;/button&gt;        &lt;/div&gt;        &lt;button @click=&quot;removeItem(item.id)&quot; class=&quot;remove&quot;&gt;删除&lt;/button&gt;      &lt;/div&gt;    &lt;/div&gt;    &lt;!-- 统计信息 --&gt;    &lt;div class=&quot;summary&quot;&gt;      &lt;p&gt;总数量: &#123;&#123; totalCount &#125;&#125;&lt;/p&gt;      &lt;p&gt;总价: ¥&#123;&#123; totalPrice.toFixed(2) &#125;&#125;&lt;/p&gt;    &lt;/div&gt;    &lt;button @click=&quot;clearCart&quot; v-if=&quot;cart.items.length &gt; 0&quot;&gt;清空购物车&lt;/button&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; reactive, computed &#125; from &#x27;vue&#x27;const cart = reactive(&#123;  items: [    &#123; id: 1, name: &#x27;iPhone 15&#x27;, price: 7999, quantity: 1 &#125;,    &#123; id: 2, name: &#x27;MacBook Pro&#x27;, price: 14999, quantity: 2 &#125;,    &#123; id: 3, name: &#x27;AirPods Pro&#x27;, price: 1899, quantity: 1 &#125;  ]&#125;)// 计算属性：总数量const totalCount = computed(() =&gt; &#123;  return cart.items.reduce((sum, item) =&gt; sum + item.quantity, 0)&#125;)// 计算属性：总价const totalPrice = computed(() =&gt; &#123;  return cart.items.reduce((sum, item) =&gt; sum + item.price * item.quantity, 0)&#125;)function increaseQuantity(item) &#123;  item.quantity++&#125;function decreaseQuantity(item) &#123;  if (item.quantity &gt; 1) &#123;    item.quantity--  &#125;&#125;function removeItem(id) &#123;  const index = cart.items.findIndex(item =&gt; item.id === id)  if (index &gt; -1) &#123;    cart.items.splice(index, 1)  &#125;&#125;function clearCart() &#123;  cart.items = []&#125;&lt;/script&gt;&lt;style scoped&gt;.cart &#123;  max-width: 600px;  margin: 20px auto;  padding: 20px;  border: 1px solid #eee;  border-radius: 8px;&#125;.product-item &#123;  display: flex;  justify-content: space-between;  align-items: center;  padding: 10px 0;  border-bottom: 1px solid #eee;&#125;.quantity &#123;  display: flex;  align-items: center;  gap: 8px;&#125;.quantity button &#123;  width: 24px;  height: 24px;&#125;.remove &#123;  background: #ff4d4f;  color: white;  border: none;  padding: 4px 12px;  cursor: pointer;&#125;.summary &#123;  margin-top: 20px;  padding: 10px;  background: #f5f5f5;&#125;&lt;/style&gt;


四、指令系统4.1 条件渲染 v-if &#x2F; v-else&lt;template&gt;  &lt;!-- v-if 会真正销毁和重建元素 --&gt;  &lt;div v-if=&quot;type === &#x27;A&#x27;&quot;&gt;类型 A&lt;/div&gt;  &lt;div v-else-if=&quot;type === &#x27;B&#x27;&quot;&gt;类型 B&lt;/div&gt;  &lt;div v-else&gt;其他类型&lt;/div&gt;  &lt;!-- v-show 只是切换 display 样式 --&gt;  &lt;div v-show=&quot;isVisible&quot;&gt;可显示/隐藏&lt;/div&gt;  &lt;button @click=&quot;toggle&quot;&gt;切换&lt;/button&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref &#125; from &#x27;vue&#x27;const type = ref(&#x27;A&#x27;)const isVisible = ref(true)function toggle() &#123;  isVisible.value = !isVisible.value  type.value = type.value === &#x27;A&#x27; ? &#x27;B&#x27; : &#x27;A&#x27;&#125;&lt;/script&gt;

4.2 列表渲染 v-for&lt;template&gt;  &lt;!-- 遍历数组 --&gt;  &lt;ul&gt;    &lt;li v-for=&quot;item in items&quot; :key=&quot;item.id&quot;&gt;      &#123;&#123; item.name &#125;&#125;    &lt;/li&gt;  &lt;/ul&gt;  &lt;!-- 遍历对象 --&gt;  &lt;ul&gt;    &lt;li v-for=&quot;(value, key) in object&quot; :key=&quot;key&quot;&gt;      &#123;&#123; key &#125;&#125;: &#123;&#123; value &#125;&#125;    &lt;/li&gt;  &lt;/ul&gt;  &lt;!-- 使用索引 --&gt;  &lt;ul&gt;    &lt;li v-for=&quot;(item, index) in items&quot; :key=&quot;item.id&quot;&gt;      &#123;&#123; index &#125;&#125; - &#123;&#123; item.name &#125;&#125;    &lt;/li&gt;  &lt;/ul&gt;&lt;/template&gt;&lt;script setup&gt;const items = [  &#123; id: 1, name: &#x27;Apple&#x27; &#125;,  &#123; id: 2, name: &#x27;Banana&#x27; &#125;,  &#123; id: 3, name: &#x27;Orange&#x27; &#125;]const object = &#123;  name: &#x27;Vue&#x27;,  version: &#x27;3&#x27;,  author: &#x27;Evan You&#x27;&#125;&lt;/script&gt;

4.3 其他常用指令&lt;template&gt;  &lt;!-- v-bind 缩写 --&gt;  &lt;img :src=&quot;imageSrc&quot; :alt=&quot;imageAlt&quot;&gt;  &lt;!-- v-on 缩写 --&gt;  &lt;button @click=&quot;handleClick&quot;&gt;点击&lt;/button&gt;  &lt;!-- v-model 双向绑定 --&gt;  &lt;input v-model=&quot;inputText&quot;&gt;  &lt;textarea v-model=&quot;textareaValue&quot;&gt;&lt;/textarea&gt;  &lt;select v-model=&quot;selected&quot;&gt;    &lt;option value=&quot;a&quot;&gt;A&lt;/option&gt;    &lt;option value=&quot;b&quot;&gt;B&lt;/option&gt;  &lt;/select&gt;  &lt;!-- v-slot 缩写 --&gt;  &lt;ChildComponent&gt;    &lt;template #header&gt;      &lt;h1&gt;标题&lt;/h1&gt;    &lt;/template&gt;  &lt;/ChildComponent&gt;  &lt;!-- v-once 只渲染一次 --&gt;  &lt;span v-once&gt;&#123;&#123; neverChange &#125;&#125;&lt;/span&gt;  &lt;!-- v-pre 跳过编译 --&gt;  &lt;span v-pre&gt;&#123;&#123; this will not be compiled &#125;&#125;&lt;/span&gt;  &lt;!-- v-memo 缓存子树 --&gt;  &lt;div v-memo=&quot;[value]&quot;&gt;    &#123;&#123; value &#125;&#125;  &lt;/div&gt;&lt;/template&gt;

4.4 实战案例：可过滤的列表&lt;template&gt;  &lt;div class=&quot;filterable-list&quot;&gt;    &lt;input      v-model=&quot;searchQuery&quot;      placeholder=&quot;搜索...&quot;      class=&quot;search-input&quot;    &gt;    &lt;select v-model=&quot;sortBy&quot; class=&quot;sort-select&quot;&gt;      &lt;option value=&quot;name&quot;&gt;按名称排序&lt;/option&gt;      &lt;option value=&quot;price&quot;&gt;按价格排序&lt;/option&gt;      &lt;option value=&quot;stock&quot;&gt;按库存排序&lt;/option&gt;    &lt;/select&gt;    &lt;ul class=&quot;product-list&quot;&gt;      &lt;li v-for=&quot;product in filteredProducts&quot; :key=&quot;product.id&quot; class=&quot;product-item&quot;&gt;        &lt;span class=&quot;name&quot;&gt;&#123;&#123; product.name &#125;&#125;&lt;/span&gt;        &lt;span class=&quot;price&quot;&gt;¥&#123;&#123; product.price &#125;&#125;&lt;/span&gt;        &lt;span class=&quot;stock&quot; :class=&quot;&#123; &#x27;low-stock&#x27;: product.stock &lt; 10 &#125;&quot;&gt;          库存: &#123;&#123; product.stock &#125;&#125;        &lt;/span&gt;      &lt;/li&gt;    &lt;/ul&gt;    &lt;p v-if=&quot;filteredProducts.length === 0&quot;&gt;没有找到匹配的商品&lt;/p&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref, computed &#125; from &#x27;vue&#x27;const searchQuery = ref(&#x27;&#x27;)const sortBy = ref(&#x27;name&#x27;)const products = ref([  &#123; id: 1, name: &#x27;iPhone 15 Pro&#x27;, price: 8999, stock: 50 &#125;,  &#123; id: 2, name: &#x27;MacBook Air M2&#x27;, price: 9499, stock: 30 &#125;,  &#123; id: 3, name: &#x27;AirPods Pro 2&#x27;, price: 1899, stock: 8 &#125;,  &#123; id: 4, name: &#x27;iPad Pro&#x27;, price: 6799, stock: 20 &#125;,  &#123; id: 5, name: &#x27;Apple Watch&#x27;, price: 2999, stock: 5 &#125;])const filteredProducts = computed(() =&gt; &#123;  let result = products.value.filter(product =&gt;    product.name.toLowerCase().includes(searchQuery.value.toLowerCase())  )  // 排序  result.sort((a, b) =&gt; &#123;    if (sortBy.value === &#x27;name&#x27;) &#123;      return a.name.localeCompare(b.name)    &#125; else if (sortBy.value === &#x27;price&#x27;) &#123;      return a.price - b.price    &#125; else &#123;      return a.stock - b.stock    &#125;  &#125;)  return result&#125;)&lt;/script&gt;&lt;style scoped&gt;.filterable-list &#123;  max-width: 600px;  margin: 20px auto;&#125;.search-input, .sort-select &#123;  padding: 8px 12px;  margin-right: 10px;  border: 1px solid #ddd;  border-radius: 4px;&#125;.product-list &#123;  list-style: none;  padding: 0;&#125;.product-item &#123;  display: flex;  justify-content: space-between;  padding: 12px;  border-bottom: 1px solid #eee;&#125;.low-stock &#123;  color: #ff4d4f;  font-weight: bold;&#125;&lt;/style&gt;


五、事件处理5.1 内联事件处理器&lt;template&gt;  &lt;!-- 内联语句 --&gt;  &lt;button @click=&quot;count++&quot;&gt;增加 &#123;&#123; count &#125;&#125;&lt;/button&gt;  &lt;!-- 访问事件对象 --&gt;  &lt;button @click=&quot;handleClick($event)&quot;&gt;点击&lt;/button&gt;  &lt;!-- 传递参数 --&gt;  &lt;button @click=&quot;say(&#x27;hello&#x27;)&quot;&gt;Say hello&lt;/button&gt;  &lt;button @click=&quot;say(&#x27;hello&#x27;, $event)&quot;&gt;Say hello with event&lt;/button&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref &#125; from &#x27;vue&#x27;const count = ref(0)function handleClick(event) &#123;  console.log(event.target.tagName) // BUTTON&#125;function say(message, event) &#123;  console.log(message)  if (event) &#123;    console.log(event.target)  &#125;&#125;&lt;/script&gt;

5.2 事件修饰符&lt;template&gt;  &lt;!-- 阻止默认行为 --&gt;  &lt;form @submit.prevent=&quot;onSubmit&quot;&gt;    &lt;button type=&quot;submit&quot;&gt;提交&lt;/button&gt;  &lt;/form&gt;  &lt;!-- 阻止事件冒泡 --&gt;  &lt;div @click=&quot;onDivClick&quot;&gt;    &lt;button @click.stop=&quot;onButtonClick&quot;&gt;按钮&lt;/button&gt;  &lt;/div&gt;  &lt;!-- 事件只触发一次 --&gt;  &lt;button @click.once=&quot;onOnceClick&quot;&gt;只触发一次&lt;/button&gt;  &lt;!-- 捕获模式 --&gt;  &lt;div @click.capture=&quot;onCapture&quot;&gt;    &lt;button @click=&quot;onBubble&quot;&gt;测试捕获&lt;/button&gt;  &lt;/div&gt;  &lt;!-- 只当事件在该元素本身触发时触发 --&gt;  &lt;div @click.self=&quot;onSelf&quot;&gt;    &lt;button @click=&quot;onButton&quot;&gt;按钮&lt;/button&gt;  &lt;/div&gt;  &lt;!-- 链式修饰符 --&gt;  &lt;form @submit.prevent.stop=&quot;onSubmit&quot;&gt;&lt;/form&gt;&lt;/template&gt;

5.3 按键修饰符&lt;template&gt;  &lt;!-- 按键修饰符 --&gt;  &lt;input @keyup.enter=&quot;onEnter&quot;&gt;  &lt;input @keyup.tab=&quot;onTab&quot;&gt;  &lt;input @keyup.delete=&quot;onDelete&quot;&gt;  &lt;input @keyup.esc=&quot;onEsc&quot;&gt;  &lt;input @keyup.space=&quot;onSpace&quot;&gt;  &lt;input @keyup.up=&quot;onUp&quot;&gt;  &lt;input @keyup.down=&quot;onDown&quot;&gt;  &lt;input @keyup.left=&quot;onLeft&quot;&gt;  &lt;input @keyup.right=&quot;onRight&quot;&gt;  &lt;!-- 系统修饰符 --&gt;  &lt;input @keyup.ctrl=&quot;onCtrl&quot;&gt;  &lt;input @keyup.alt=&quot;onAlt&quot;&gt;  &lt;input @keyup.shift=&quot;onShift&quot;&gt;  &lt;input @keyup.meta=&quot;onMeta&quot;&gt; &lt;!-- Mac 的 Command 键 --&gt;  &lt;!-- 组合使用 --&gt;  &lt;input @keyup.ctrl.enter=&quot;onCtrlEnter&quot;&gt;  &lt;input @click.ctrl=&quot;onClickCtrl&quot;&gt;  &lt;!-- exact 修饰符 --&gt;  &lt;button @click.ctrl.exact=&quot;onCtrlOnly&quot;&gt;只有 Ctrl&lt;/button&gt;  &lt;button @click.exact=&quot;onExact&quot;&gt;没有任何修饰键&lt;/button&gt;&lt;/template&gt;

5.4 实战案例：表单提交&lt;template&gt;  &lt;form @submit.prevent=&quot;handleSubmit&quot; class=&quot;form&quot;&gt;    &lt;h2&gt;用户注册&lt;/h2&gt;    &lt;div class=&quot;form-group&quot;&gt;      &lt;label&gt;用户名:&lt;/label&gt;      &lt;input        v-model=&quot;form.username&quot;        @keyup.enter=&quot;focusEmail&quot;        placeholder=&quot;按 Enter 跳转到邮箱&quot;        required      &gt;    &lt;/div&gt;    &lt;div class=&quot;form-group&quot;&gt;      &lt;label&gt;邮箱:&lt;/label&gt;      &lt;input        ref=&quot;emailInput&quot;        v-model=&quot;form.email&quot;        type=&quot;email&quot;        @keyup.enter=&quot;focusPassword&quot;        placeholder=&quot;按 Enter 跳转到密码&quot;        required      &gt;    &lt;/div&gt;    &lt;div class=&quot;form-group&quot;&gt;      &lt;label&gt;密码:&lt;/label&gt;      &lt;input        ref=&quot;passwordInput&quot;        v-model=&quot;form.password&quot;        type=&quot;password&quot;        @keyup.enter=&quot;handleSubmit&quot;        placeholder=&quot;按 Enter 提交&quot;        required      &gt;    &lt;/div&gt;    &lt;div class=&quot;form-group&quot;&gt;      &lt;label&gt;        &lt;input type=&quot;checkbox&quot; v-model=&quot;form.agree&quot; required&gt;        同意用户协议      &lt;/label&gt;    &lt;/div&gt;    &lt;button type=&quot;submit&quot; :disabled=&quot;!form.agree&quot;&gt;注册&lt;/button&gt;    &lt;button type=&quot;button&quot; @click.ctrl=&quot;resetForm&quot;&gt;Ctrl + 点击重置&lt;/button&gt;  &lt;/form&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref, reactive &#125; from &#x27;vue&#x27;const emailInput = ref(null)const passwordInput = ref(null)const form = reactive(&#123;  username: &#x27;&#x27;,  email: &#x27;&#x27;,  password: &#x27;&#x27;,  agree: false&#125;)function focusEmail() &#123;  emailInput.value.focus()&#125;function focusPassword() &#123;  passwordInput.value.focus()&#125;function handleSubmit() &#123;  if (!form.agree) &#123;    alert(&#x27;请同意用户协议&#x27;)    return  &#125;  console.log(&#x27;提交表单:&#x27;, form)  alert(&#x27;注册成功！&#x27;)&#125;function resetForm() &#123;  form.username = &#x27;&#x27;  form.email = &#x27;&#x27;  form.password = &#x27;&#x27;  form.agree = false&#125;&lt;/script&gt;&lt;style scoped&gt;.form &#123;  max-width: 400px;  margin: 20px auto;  padding: 20px;  border: 1px solid #eee;  border-radius: 8px;&#125;.form-group &#123;  margin-bottom: 15px;&#125;.form-group label &#123;  display: block;  margin-bottom: 5px;  font-weight: bold;&#125;.form-group input &#123;  width: 100%;  padding: 8px;  border: 1px solid #ddd;  border-radius: 4px;&#125;button &#123;  margin-right: 10px;  padding: 8px 16px;  cursor: pointer;&#125;button:disabled &#123;  opacity: 0.5;  cursor: not-allowed;&#125;&lt;/style&gt;


六、计算属性与侦听器6.1 计算属性 computed&lt;template&gt;  &lt;p&gt;原价: &#123;&#123; price &#125;&#125;&lt;/p&gt;  &lt;p&gt;折扣价: &#123;&#123; discountedPrice &#125;&#125;&lt;/p&gt;  &lt;p&gt;最终价格: &#123;&#123; formatPrice(discountedPrice) &#125;&#125;&lt;/p&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref, computed &#125; from &#x27;vue&#x27;const price = ref(100)// 计算属性（有缓存）const discountedPrice = computed(() =&gt; &#123;  return price.value * 0.8&#125;)// 可写计算属性const fullName = computed(&#123;  get() &#123;    return firstName.value + &#x27; &#x27; + lastName.value  &#125;,  set(newValue) &#123;    [firstName.value, lastName.value] = newValue.split(&#x27; &#x27;)  &#125;&#125;)function formatPrice(value) &#123;  return &#x27;¥&#x27; + value.toFixed(2)&#125;&lt;/script&gt;

6.2 侦听器 watch&lt;template&gt;  &lt;input v-model=&quot;searchQuery&quot; placeholder=&quot;搜索...&quot;&gt;  &lt;p&gt;搜索结果: &#123;&#123; searchResult &#125;&#125;&lt;/p&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref, watch &#125; from &#x27;vue&#x27;const searchQuery = ref(&#x27;&#x27;)const searchResult = ref(&#x27;&#x27;)// 侦听单个 refwatch(searchQuery, (newValue, oldValue) =&gt; &#123;  console.log(`搜索词从 &quot;$&#123;oldValue&#125;&quot; 变为 &quot;$&#123;newValue&#125;&quot;`)  // 模拟异步搜索  setTimeout(() =&gt; &#123;    searchResult.value = `搜索 &quot;$&#123;newValue&#125;&quot; 的结果...`  &#125;, 500)&#125;)// 立即执行watch(searchQuery, (newValue) =&gt; &#123;  // ...&#125;, &#123; immediate: true &#125;)// 深度侦听对象const user = ref(&#123; name: &#x27;张三&#x27;, age: 25 &#125;)watch(user, (newValue) =&gt; &#123;  console.log(&#x27;user 发生变化:&#x27;, newValue)&#125;, &#123; deep: true &#125;)&lt;/script&gt;

6.3 watchEffect&lt;script setup&gt;import &#123; ref, watchEffect &#125; from &#x27;vue&#x27;const count = ref(0)const name = ref(&#x27;Vue&#x27;)// 自动追踪依赖watchEffect(() =&gt; &#123;  console.log(`count 是 $&#123;count.value&#125;, name 是 $&#123;name.value&#125;`)  // 只要 count 或 name 变化，就会重新执行&#125;)// 停止侦听const stop = watchEffect(() =&gt; &#123;  /* ... */&#125;)// 调用 stop() 可以停止侦听&lt;/script&gt;

6.4 实战案例：实时搜索&lt;template&gt;  &lt;div class=&quot;search-demo&quot;&gt;    &lt;input      v-model=&quot;searchQuery&quot;      placeholder=&quot;输入搜索关键词...&quot;      class=&quot;search-input&quot;    &gt;    &lt;div v-if=&quot;isLoading&quot; class=&quot;loading&quot;&gt;搜索中...&lt;/div&gt;    &lt;div v-else&gt;      &lt;h3&gt;搜索结果 (&#123;&#123; results.length &#125;&#125;)&lt;/h3&gt;      &lt;ul v-if=&quot;results.length &gt; 0&quot;&gt;        &lt;li v-for=&quot;item in results&quot; :key=&quot;item.id&quot;&gt;          &#123;&#123; item.name &#125;&#125; - &#123;&#123; item.category &#125;&#125;        &lt;/li&gt;      &lt;/ul&gt;      &lt;p v-else-if=&quot;searchQuery &amp;&amp; !isLoading&quot;&gt;没有找到匹配结果&lt;/p&gt;    &lt;/div&gt;    &lt;div class=&quot;history&quot; v-if=&quot;searchHistory.length &gt; 0&quot;&gt;      &lt;h4&gt;搜索历史:&lt;/h4&gt;      &lt;span        v-for=&quot;term in searchHistory&quot;        :key=&quot;term&quot;        @click=&quot;searchQuery = term&quot;        class=&quot;history-item&quot;      &gt;        &#123;&#123; term &#125;&#125;      &lt;/span&gt;    &lt;/div&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref, watch &#125; from &#x27;vue&#x27;const searchQuery = ref(&#x27;&#x27;)const results = ref([])const isLoading = ref(false)const searchHistory = ref([])// 模拟数据库const database = [  &#123; id: 1, name: &#x27;iPhone 15 Pro&#x27;, category: &#x27;手机&#x27; &#125;,  &#123; id: 2, name: &#x27;MacBook Pro&#x27;, category: &#x27;电脑&#x27; &#125;,  &#123; id: 3, name: &#x27;AirPods Pro&#x27;, category: &#x27;配件&#x27; &#125;,  &#123; id: 4, name: &#x27;iPad Air&#x27;, category: &#x27;平板&#x27; &#125;,  &#123; id: 5, name: &#x27;Apple Watch&#x27;, category: &#x27;手表&#x27; &#125;,  &#123; id: 6, name: &#x27;Mac mini&#x27;, category: &#x27;电脑&#x27; &#125;,  &#123; id: 7, name: &#x27;iMac&#x27;, category: &#x27;电脑&#x27; &#125;]// 防抖函数function debounce(fn, delay) &#123;  let timer = null  return function(...args) &#123;    if (timer) clearTimeout(timer)    timer = setTimeout(() =&gt; &#123;      fn.apply(this, args)    &#125;, delay)  &#125;&#125;// 模拟搜索APIfunction searchAPI(query) &#123;  return new Promise((resolve) =&gt; &#123;    setTimeout(() =&gt; &#123;      const filtered = database.filter(item =&gt;        item.name.toLowerCase().includes(query.toLowerCase())      )      resolve(filtered)    &#125;, 300)  &#125;)&#125;// 侦听搜索词变化（带防抖）watch(searchQuery, debounce(async (newQuery) =&gt; &#123;  if (!newQuery.trim()) &#123;    results.value = []    return  &#125;  isLoading.value = true  try &#123;    results.value = await searchAPI(newQuery)    // 添加到搜索历史    if (!searchHistory.value.includes(newQuery)) &#123;      searchHistory.value.unshift(newQuery)      if (searchHistory.value.length &gt; 5) &#123;        searchHistory.value.pop()      &#125;    &#125;  &#125; finally &#123;    isLoading.value = false  &#125;&#125;, 500))&lt;/script&gt;&lt;style scoped&gt;.search-demo &#123;  max-width: 600px;  margin: 20px auto;&#125;.search-input &#123;  width: 100%;  padding: 12px;  border: 1px solid #ddd;  border-radius: 4px;  font-size: 16px;&#125;.loading &#123;  color: #666;  padding: 20px;&#125;.history-item &#123;  display: inline-block;  margin: 5px;  padding: 4px 12px;  background: #f0f0f0;  border-radius: 12px;  cursor: pointer;&#125;.history-item:hover &#123;  background: #e0e0e0;&#125;&lt;/style&gt;



💡 小结：本章介绍了 Vue.js 的核心基础语法，包括创建应用、模板语法、响应式数据、指令系统和事件处理。每个知识点都配有实战案例，建议动手实践加深理解。

Vue Router 路由管理一、Vue Router 基础1.1 什么是 Vue RouterVue Router 是 Vue.js 的官方路由管理器,它深度集成于 Vue.js 核心,让构建单页面应用变得轻而易举。主要功能包括:

嵌套路由映射
动态路由选择
模块化、基于组件的路由配置
导航控制
HTML5 history 模式或 hash 模式

1.2 安装与配置安装npm install vue-router@4

基本配置// router/index.jsimport &#123; createRouter, createWebHistory &#125; from &#x27;vue-router&#x27;import Home from &#x27;../views/Home.vue&#x27;import About from &#x27;../views/About.vue&#x27;const routes = [  &#123;    path: &#x27;/&#x27;,    name: &#x27;Home&#x27;,    component: Home  &#125;,  &#123;    path: &#x27;/about&#x27;,    name: &#x27;About&#x27;,    component: About  &#125;]const router = createRouter(&#123;  history: createWebHistory(process.env.BASE_URL),  routes&#125;)export default router

// main.jsimport &#123; createApp &#125; from &#x27;vue&#x27;import App from &#x27;./App.vue&#x27;import router from &#x27;./router&#x27;const app = createApp(App)app.use(router)app.mount(&#x27;#app&#x27;)

&lt;!-- App.vue --&gt;&lt;template&gt;  &lt;div id=&quot;app&quot;&gt;    &lt;nav&gt;      &lt;router-link to=&quot;/&quot;&gt;首页&lt;/router-link&gt; |      &lt;router-link to=&quot;/about&quot;&gt;关于&lt;/router-link&gt;    &lt;/nav&gt;    &lt;router-view /&gt;  &lt;/div&gt;&lt;/template&gt;

实践练习1: 搭建一个包含首页、产品列表和产品详情的基础路由系统
// router/index.jsimport &#123; createRouter, createWebHistory &#125; from &#x27;vue-router&#x27;const routes = [  &#123;    path: &#x27;/&#x27;,    name: &#x27;Home&#x27;,    component: () =&gt; import(&#x27;../views/Home.vue&#x27;),    meta: &#123;      title: &#x27;首页&#x27;    &#125;  &#125;,  &#123;    path: &#x27;/products&#x27;,    name: &#x27;Products&#x27;,    component: () =&gt; import(&#x27;../views/Products.vue&#x27;),    meta: &#123;      title: &#x27;产品列表&#x27;    &#125;  &#125;,  &#123;    path: &#x27;/products/:id&#x27;,    name: &#x27;ProductDetail&#x27;,    component: () =&gt; import(&#x27;../views/ProductDetail.vue&#x27;),    meta: &#123;      title: &#x27;产品详情&#x27;    &#125;  &#125;]const router = createRouter(&#123;  history: createWebHistory(),  routes,  scrollBehavior(to, from, savedPosition) &#123;    // 滚动到顶部    return &#123; top: 0 &#125;  &#125;&#125;)export default router


二、嵌套路由2.1 基本嵌套路由// router/index.jsconst routes = [  &#123;    path: &#x27;/user/:id&#x27;,    component: User,    children: [      &#123;        // 当 /user/:id/profile 匹配成功        path: &#x27;profile&#x27;,        component: UserProfile      &#125;,      &#123;        // 当 /user/:id/posts 匹配成功        path: &#x27;posts&#x27;,        component: UserPosts      &#125;    ]  &#125;]

&lt;!-- User.vue --&gt;&lt;template&gt;  &lt;div class=&quot;user&quot;&gt;    &lt;h2&gt;用户中心&lt;/h2&gt;    &lt;router-view /&gt;  &lt;/div&gt;&lt;/template&gt;

2.2 多级嵌套const routes = [  &#123;    path: &#x27;/admin&#x27;,    component: Admin,    children: [      &#123;        path: &#x27;dashboard&#x27;,        component: Dashboard      &#125;,      &#123;        path: &#x27;users&#x27;,        component: UserManagement,        children: [          &#123;            path: &#x27;list&#x27;,            component: UserList          &#125;,          &#123;            path: &#x27;create&#x27;,            component: CreateUser          &#125;,          &#123;            path: &#x27;edit/:id&#x27;,            component: EditUser          &#125;        ]      &#125;,      &#123;        path: &#x27;settings&#x27;,        component: Settings      &#125;    ]  &#125;]

