实践练习4: 创建一个搜索页面,实现搜索历史记录功能
&lt;!-- Search.vue --&gt;&lt;template&gt;  &lt;div class=&quot;search-page&quot;&gt;    &lt;div class=&quot;search-box&quot;&gt;      &lt;input        v-model=&quot;keyword&quot;        @keyup.enter=&quot;search&quot;        placeholder=&quot;搜索...&quot;      /&gt;      &lt;button @click=&quot;search&quot;&gt;搜索&lt;/button&gt;    &lt;/div&gt;        &lt;div class=&quot;search-history&quot;&gt;      &lt;h3&gt;搜索历史&lt;/h3&gt;      &lt;ul&gt;        &lt;li v-for=&quot;(item, index) in searchHistory&quot; :key=&quot;index&quot;&gt;          &lt;a @click=&quot;searchFromHistory(item)&quot;&gt;&#123;&#123; item &#125;&#125;&lt;/a&gt;          &lt;button @click=&quot;removeHistory(index)&quot;&gt;×&lt;/button&gt;        &lt;/li&gt;      &lt;/ul&gt;      &lt;button v-if=&quot;searchHistory.length&quot; @click=&quot;clearHistory&quot;&gt;        清空历史      &lt;/button&gt;    &lt;/div&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script&gt;export default &#123;  name: &#x27;Search&#x27;,  data() &#123;    return &#123;      keyword: &#x27;&#x27;,      searchHistory: []    &#125;  &#125;,    created() &#123;    // 从路由参数恢复搜索关键词    if (this.$route.query.q) &#123;      this.keyword = this.$route.query.q      this.loadSearchResults()    &#125;        // 从 localStorage 加载搜索历史    const history = localStorage.getItem(&#x27;searchHistory&#x27;)    if (history) &#123;      this.searchHistory = JSON.parse(history)    &#125;  &#125;,    methods: &#123;    search() &#123;      if (!this.keyword.trim()) return            // 添加到搜索历史      this.addToHistory(this.keyword)            // 使用 replace 避免产生过多历史记录      this.$router.replace(&#123;        path: &#x27;/search&#x27;,        query: &#123; q: this.keyword &#125;      &#125;)            this.loadSearchResults()    &#125;,        searchFromHistory(keyword) &#123;      this.keyword = keyword      this.$router.push(&#123;        path: &#x27;/search&#x27;,        query: &#123; q: keyword &#125;      &#125;)      this.loadSearchResults()    &#125;,        addToHistory(keyword) &#123;      // 移除重复项      this.searchHistory = this.searchHistory.filter(k =&gt; k !== keyword)      // 添加到开头      this.searchHistory.unshift(keyword)      // 限制最多 10 条      if (this.searchHistory.length &gt; 10) &#123;        this.searchHistory.pop()      &#125;      // 保存到 localStorage      localStorage.setItem(&#x27;searchHistory&#x27;, JSON.stringify(this.searchHistory))    &#125;,        removeHistory(index) &#123;      this.searchHistory.splice(index, 1)      localStorage.setItem(&#x27;searchHistory&#x27;, JSON.stringify(this.searchHistory))    &#125;,        clearHistory() &#123;      this.searchHistory = []      localStorage.removeItem(&#x27;searchHistory&#x27;)    &#125;,        loadSearchResults() &#123;      // 加载搜索结果      console.log(&#x27;搜索:&#x27;, this.keyword)    &#125;  &#125;&#125;&lt;/script&gt;


五、导航守卫5.1 全局前置守卫// router/index.jsimport &#123; createRouter, createWebHistory &#125; from &#x27;vue-router&#x27;import &#123; useAuthStore &#125; from &#x27;../stores/auth&#x27;const router = createRouter(&#123;  history: createWebHistory(),  routes&#125;)// 全局前置守卫router.beforeEach((to, from) =&gt; &#123;  // 设置页面标题  document.title = to.meta.title || &#x27;Vue App&#x27;    const authStore = useAuthStore()    // 需要登录的页面  if (to.meta.requiresAuth &amp;&amp; !authStore.isLoggedIn) &#123;    // 保存目标路由,登录后重定向    return &#123;      path: &#x27;/login&#x27;,      query: &#123; redirect: to.fullPath &#125;    &#125;  &#125;    // 已登录用户访问登录页  if (to.path === &#x27;/login&#x27; &amp;&amp; authStore.isLoggedIn) &#123;    return &#123; path: &#x27;/&#x27; &#125;  &#125;    // 允许导航  return true&#125;)export default router

5.2 全局后置钩子router.afterEach((to, from) =&gt; &#123;  // 发送页面浏览统计  analytics.logPageView(to.fullPath)    // 滚动到页面顶部  window.scrollTo(0, 0)&#125;)

5.3 路由独享守卫const routes = [  &#123;    path: &#x27;/admin&#x27;,    component: Admin,    beforeEnter: (to, from) =&gt; &#123;      const authStore = useAuthStore()            // 检查管理员权限      if (!authStore.isAdmin) &#123;        return &#123; path: &#x27;/403&#x27; &#125;      &#125;            return true    &#125;  &#125;]

5.4 组件内守卫&lt;script&gt;export default &#123;  data() &#123;    return &#123;      user: null,      saved: true // 是否已保存    &#125;  &#125;,    async beforeRouteEnter(to, from, next) &#123;    // 在渲染该组件的对应路由被验证前调用    // 此时组件实例还没被创建,无法访问 this    const user = await fetchUser(to.params.id)    next(vm =&gt; &#123;      // 通过回调访问组件实例      vm.user = user    &#125;)  &#125;,    beforeRouteUpdate(to, from) &#123;    // 在当前路由改变,但是该组件被复用时调用    // 例如从 /users/1 到 /users/2    this.loadUser(to.params.id)  &#125;,    beforeRouteLeave(to, from) &#123;    // 导航离开该组件的对应路由时调用    if (!this.saved) &#123;      const answer = window.confirm(        &#x27;数据未保存,确定要离开吗?&#x27;      )      if (!answer) return false    &#125;  &#125;,    methods: &#123;    async loadUser(id) &#123;      this.user = await fetchUser(id)    &#125;  &#125;&#125;&lt;/script&gt;

实践练习5: 实现一个完整的权限控制系统
// router/permissions.jsimport &#123; useAuthStore &#125; from &#x27;@/stores/auth&#x27;// 权限检查函数function checkPermission(to) &#123;  const authStore = useAuthStore()  const &#123; requiresAuth, roles, permissions &#125; = to.meta    // 不需要登录  if (!requiresAuth) &#123;    return true  &#125;    // 未登录  if (!authStore.isLoggedIn) &#123;    return &#123;      path: &#x27;/login&#x27;,      query: &#123; redirect: to.fullPath &#125;    &#125;  &#125;    // 检查角色  if (roles &amp;&amp; !roles.some(role =&gt; authStore.user.roles.includes(role))) &#123;    return &#123; path: &#x27;/403&#x27; &#125;  &#125;    // 检查权限  if (permissions &amp;&amp; !permissions.some(p =&gt; authStore.hasPermission(p))) &#123;    return &#123; path: &#x27;/403&#x27; &#125;  &#125;    return true&#125;// 设置路由守卫export function setupRouterGuards(router) &#123;  // 全局前置守卫  router.beforeEach(async (to, from) =&gt; &#123;    // 显示加载状态    const loadingStore = useLoadingStore()    loadingStore.show()        // 检查权限    return checkPermission(to)  &#125;)    // 全局后置钩子  router.afterEach((to, from) =&gt; &#123;    // 隐藏加载状态    const loadingStore = useLoadingStore()    loadingStore.hide()        // 设置页面标题    if (to.meta.title) &#123;      document.title = `$&#123;to.meta.title&#125; - Vue Admin`    &#125;        // 页面统计    trackPageView(to)  &#125;)    // 错误处理  router.onError((error) =&gt; &#123;    console.error(&#x27;路由错误:&#x27;, error)    // 跳转到错误页面    router.push(&#x27;/error&#x27;)  &#125;)&#125;

// router/index.jsimport &#123; createRouter, createWebHistory &#125; from &#x27;vue-router&#x27;import &#123; setupRouterGuards &#125; from &#x27;./permissions&#x27;const routes = [  &#123;    path: &#x27;/login&#x27;,    name: &#x27;Login&#x27;,    component: () =&gt; import(&#x27;@/views/Login.vue&#x27;),    meta: &#123; title: &#x27;登录&#x27; &#125;  &#125;,  &#123;    path: &#x27;/&#x27;,    component: () =&gt; import(&#x27;@/layouts/MainLayout.vue&#x27;),    meta: &#123; requiresAuth: true &#125;,    children: [      &#123;        path: &#x27;&#x27;,        name: &#x27;Dashboard&#x27;,        component: () =&gt; import(&#x27;@/views/Dashboard.vue&#x27;),        meta: &#123; title: &#x27;仪表盘&#x27; &#125;      &#125;,      &#123;        path: &#x27;users&#x27;,        name: &#x27;Users&#x27;,        component: () =&gt; import(&#x27;@/views/Users.vue&#x27;),        meta: &#123;           title: &#x27;用户管理&#x27;,          requiresAuth: true,          roles: [&#x27;admin&#x27;],          permissions: [&#x27;user:view&#x27;]        &#125;      &#125;,      &#123;        path: &#x27;settings&#x27;,        name: &#x27;Settings&#x27;,        component: () =&gt; import(&#x27;@/views/Settings.vue&#x27;),        meta: &#123;           title: &#x27;系统设置&#x27;,          requiresAuth: true,          roles: [&#x27;admin&#x27;, &#x27;manager&#x27;]        &#125;      &#125;    ]  &#125;,  &#123;    path: &#x27;/403&#x27;,    name: &#x27;Forbidden&#x27;,    component: () =&gt; import(&#x27;@/views/errors/Forbidden.vue&#x27;),    meta: &#123; title: &#x27;无权限&#x27; &#125;  &#125;,  &#123;    path: &#x27;/:pathMatch(.*)*&#x27;,    name: &#x27;NotFound&#x27;,    component: () =&gt; import(&#x27;@/views/errors/NotFound.vue&#x27;),    meta: &#123; title: &#x27;页面未找到&#x27; &#125;  &#125;]const router = createRouter(&#123;  history: createWebHistory(),  routes&#125;)// 设置路由守卫setupRouterGuards(router)export default router


