    meta: &#123; title: &#x27;我的订单&#x27; &#125;          &#125;,          &#123;            path: &#x27;order/:orderId&#x27;,            name: &#x27;OrderDetail&#x27;,            component: () =&gt; import(&#x27;@/views/user/OrderDetail.vue&#x27;),            meta: &#123; title: &#x27;订单详情&#x27; &#125;,            props: true          &#125;,          &#123;            path: &#x27;favorites&#x27;,            name: &#x27;Favorites&#x27;,            component: () =&gt; import(&#x27;@/views/user/Favorites.vue&#x27;),            meta: &#123; title: &#x27;我的收藏&#x27; &#125;          &#125;        ]      &#125;    ]  &#125;,    &#123;    path: &#x27;/login&#x27;,    name: &#x27;Login&#x27;,    component: () =&gt; import(&#x27;@/views/auth/Login.vue&#x27;),    meta: &#123; title: &#x27;登录&#x27; &#125;  &#125;,  &#123;    path: &#x27;/register&#x27;,    name: &#x27;Register&#x27;,    component: () =&gt; import(&#x27;@/views/auth/Register.vue&#x27;),    meta: &#123; title: &#x27;注册&#x27; &#125;  &#125;,    &#123;    path: &#x27;/:pathMatch(.*)*&#x27;,    name: &#x27;NotFound&#x27;,    component: () =&gt; import(&#x27;@/views/errors/NotFound.vue&#x27;),    meta: &#123; title: &#x27;页面未找到&#x27; &#125;  &#125;]const router = createRouter(&#123;  history: createWebHistory(),  routes,  scrollBehavior(to, from, savedPosition) &#123;    if (savedPosition) &#123;      return savedPosition    &#125; else if (to.hash) &#123;      return &#123; el: to.hash, behavior: &#x27;smooth&#x27; &#125;    &#125; else &#123;      return &#123; top: 0, behavior: &#x27;smooth&#x27; &#125;    &#125;  &#125;&#125;)export default router


总结Vue Router 是构建单页面应用的基石,掌握以下关键点:

路由配置: 理解路由的基本配置和路由模式
嵌套路由: 实现复杂的应用路由结构
动态路由: 灵活处理路由参数
编程式导航: 在代码中控制路由跳转
导航守卫: 实现权限控制和路由拦截

通过合理使用 Vue Router,可以构建出流畅、安全的单页面应用。
