Vue.js Composition API一、Composition API 简介1.1 什么是 Composition APIComposition API 是 Vue 3 引入的一组新的 API,用于编写组件逻辑。与 Options API 相比,Composition API 提供了更灵活的代码组织方式和更好的逻辑复用能力。
1.2 为什么使用 Composition API更好的逻辑复用

提取和复用组件逻辑更简单
避免 mixin 的命名冲突问题

更好的类型推断

对 TypeScript 支持更友好
更好的 IDE 智能提示

更灵活的代码组织

可以按功能组织代码
相关的逻辑可以放在一起

更小的生产包体积

Tree-shaking 更友好
未使用的 API 不会被打包


二、响应式基础2.1 refref 用于创建响应式的基本数据类型。
&lt;script setup&gt;import &#123; ref &#125; from &#x27;vue&#x27;// 创建响应式变量const count = ref(0)const message = ref(&#x27;Hello Vue 3&#x27;)const user = ref(&#123; name: &#x27;张三&#x27;, age: 25 &#125;)// 访问和修改值console.log(count.value) // 0count.value++ // 修改值// 在模板中自动解包,不需要 .value&lt;/script&gt;&lt;template&gt;  &lt;div&gt;    &lt;p&gt;Count: &#123;&#123; count &#125;&#125;&lt;/p&gt;    &lt;button @click=&quot;count++&quot;&gt;增加&lt;/button&gt;        &lt;p&gt;Message: &#123;&#123; message &#125;&#125;&lt;/p&gt;    &lt;input v-model=&quot;message&quot; /&gt;        &lt;p&gt;User: &#123;&#123; user.name &#125;&#125;, &#123;&#123; user.age &#125;&#125;&lt;/p&gt;  &lt;/div&gt;&lt;/template&gt;

2.2 reactivereactive 用于创建响应式的对象或数组。
&lt;script setup&gt;import &#123; reactive &#125; from &#x27;vue&#x27;// 创建响应式对象const state = reactive(&#123;  count: 0,  message: &#x27;Hello&#x27;,  user: &#123;    name: &#x27;张三&#x27;,    age: 25  &#125;&#125;)// 创建响应式数组const list = reactive([1, 2, 3, 4, 5])// 直接访问,不需要 .valueconsole.log(state.count) // 0state.count++// 添加新属性state.email = &#x27;zhangsan@example.com&#x27;// 删除属性delete state.message&lt;/script&gt;&lt;template&gt;  &lt;div&gt;    &lt;p&gt;Count: &#123;&#123; state.count &#125;&#125;&lt;/p&gt;    &lt;p&gt;User: &#123;&#123; state.user.name &#125;&#125;&lt;/p&gt;  &lt;/div&gt;&lt;/template&gt;

2.3 ref vs reactive&lt;script setup&gt;import &#123; ref, reactive, isRef, isReactive &#125; from &#x27;vue&#x27;// ref - 适合基本类型const count = ref(0)const name = ref(&#x27;张三&#x27;)// reactive - 适合对象和数组const state = reactive(&#123;  count: 0,  name: &#x27;张三&#x27;&#125;)// 对比// ref// - 可以用于任何类型的值// - 访问时需要 .value// - 可以被替换(整个对象)// - 更容易传递(可以解构)// reactive// - 只能用于对象类型// - 访问时不需要 .value// - 不能被替换(解构会失去响应性)// - 更适合复杂对象// 示例:ref 可以被替换const userRef = ref(&#123; name: &#x27;张三&#x27; &#125;)userRef.value = &#123; name: &#x27;李四&#x27; &#125; // ✅ 响应性保持// 示例:reactive 不能被替换const userReactive = reactive(&#123; name: &#x27;张三&#x27; &#125;)userReactive = &#123; name: &#x27;李四&#x27; &#125; // ❌ 失去响应性// 示例:reactive 解构会失去响应性const &#123; name &#125; = state // ❌ name 不是响应式的// 解决方案:使用 toRefsimport &#123; toRefs &#125; from &#x27;vue&#x27;const &#123; name &#125; = toRefs(state) // ✅ name 是响应式的&lt;/script&gt;

实践练习1: 创建一个计数器,理解 ref 和 reactive 的区别
&lt;template&gt;  &lt;div class=&quot;counter-demo&quot;&gt;    &lt;h2&gt;使用 ref&lt;/h2&gt;    &lt;p&gt;Count: &#123;&#123; countRef &#125;&#125;&lt;/p&gt;    &lt;button @click=&quot;countRef++&quot;&gt;增加&lt;/button&gt;    &lt;button @click=&quot;resetRef&quot;&gt;重置&lt;/button&gt;        &lt;h2&gt;使用 reactive&lt;/h2&gt;    &lt;p&gt;Count: &#123;&#123; stateReactive.count &#125;&#125;&lt;/p&gt;    &lt;button @click=&quot;stateReactive.count++&quot;&gt;增加&lt;/button&gt;    &lt;button @click=&quot;resetReactive&quot;&gt;重置&lt;/button&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref, reactive &#125; from &#x27;vue&#x27;// 使用 refconst countRef = ref(0)const resetRef = () =&gt; &#123;  countRef.value = 0&#125;// 使用 reactiveconst stateReactive = reactive(&#123;  count: 0,  name: &#x27;计数器&#x27;&#125;)const resetReactive = () =&gt; &#123;  stateReactive.count = 0&#125;&lt;/script&gt;


三、计算属性3.1 computed&lt;script setup&gt;import &#123; ref, computed &#125; from &#x27;vue&#x27;const firstName = ref(&#x27;张&#x27;)const lastName = ref(&#x27;三&#x27;)// 计算属性(只读)const fullName = computed(() =&gt; &#123;  return `$&#123;firstName.value&#125;$&#123;lastName.value&#125;`&#125;)// 计算属性(可写)const fullNameWritable = computed(&#123;  get() &#123;    return `$&#123;firstName.value&#125;$&#123;lastName.value&#125;`  &#125;,  set(newValue) &#123;    const [first, last] = newValue.split(&#x27;&#x27;)    firstName.value = first    lastName.value = last  &#125;&#125;)// 计算属性的性能优化const expensiveList = computed(() =&gt; &#123;  console.log(&#x27;计算中...&#x27;)  return Array.from(&#123; length: 1000 &#125;, (_, i) =&gt; i * 2)&#125;)&lt;/script&gt;&lt;template&gt;  &lt;div&gt;    &lt;p&gt;Full Name: &#123;&#123; fullName &#125;&#125;&lt;/p&gt;    &lt;input v-model=&quot;fullNameWritable&quot; /&gt;  &lt;/div&gt;&lt;/template&gt;

3.2 计算属性的依赖追踪&lt;script setup&gt;import &#123; ref, computed &#125; from &#x27;vue&#x27;const price = ref(100)const quantity = ref(2)const discount = ref(0.1)// 计算属性会自动追踪依赖const total = computed(() =&gt; &#123;  console.log(&#x27;重新计算 total&#x27;)  return price.value * quantity.value * (1 - discount.value)&#125;)// 只有当依赖的值改变时才会重新计算// 多次访问 total.value 只会计算一次console.log(total.value)console.log(total.value)console.log(total.value)&lt;/script&gt;


四、生命周期钩子4.1 Composition API 中的生命周期&lt;script setup&gt;import &#123;  onBeforeMount,  onMounted,  onBeforeUpdate,  onUpdated,  onBeforeUnmount,  onUnmounted,  onErrorCaptured&#125; from &#x27;vue&#x27;// 创建阶段// 没有 beforeCreate 和 created,直接在 setup 中编写// 挂载阶段onBeforeMount(() =&gt; &#123;  console.log(&#x27;组件挂载前&#x27;)&#125;)onMounted(() =&gt; &#123;  console.log(&#x27;组件挂载后&#x27;)  // DOM 操作、第三方库初始化、发送请求&#125;)// 更新阶段onBeforeUpdate(() =&gt; &#123;  console.log(&#x27;组件更新前&#x27;)&#125;)onUpdated(() =&gt; &#123;  console.log(&#x27;组件更新后&#x27;)  // 避免在此修改状态,可能导致无限循环&#125;)// 卸载阶段onBeforeUnmount(() =&gt; &#123;  console.log(&#x27;组件卸载前&#x27;)  // 清理定时器、取消订阅&#125;)onUnmounted(() =&gt; &#123;  console.log(&#x27;组件卸载后&#x27;)&#125;)// 错误捕获onErrorCaptured((err, instance, info) =&gt; &#123;  console.error(&#x27;捕获到错误:&#x27;, err)  console.log(&#x27;组件实例:&#x27;, instance)  console.log(&#x27;错误信息:&#x27;, info)    // 返回 false 阻止错误继续传播  return false&#125;)&lt;/script&gt;

4.2 实际应用场景&lt;script setup&gt;import &#123; ref, onMounted, onUnmounted &#125; from &#x27;vue&#x27;const width = ref(window.innerWidth)const height = ref(window.innerHeight)const handleResize = () =&gt; &#123;  width.value = window.innerWidth  height.value = window.innerHeight&#125;// 挂载时添加事件监听onMounted(() =&gt; &#123;  window.addEventListener(&#x27;resize&#x27;, handleResize)&#125;)// 卸载时移除事件监听onUnmounted(() =&gt; &#123;  window.removeEventListener(&#x27;resize&#x27;, handleResize)&#125;)&lt;/script&gt;&lt;template&gt;  &lt;p&gt;窗口尺寸: &#123;&#123; width &#125;&#125; x &#123;&#123; height &#125;&#125;&lt;/p&gt;&lt;/template&gt;


五、组合式函数(Composables)5.1 什么是组合式函数组合式函数是利用 Vue 的组合式 API 来封装和复用有状态逻辑的函数。它类似于 React 的自定义 Hooks。
5.2 创建组合式函数// composables/useMouse.jsimport &#123; ref, onMounted, onUnmounted &#125; from &#x27;vue&#x27;export function useMouse() &#123;  const x = ref(0)  const y = ref(0)    const update = (e) =&gt; &#123;    x.value = e.pageX    y.value = e.pageY  &#125;    onMounted(() =&gt; &#123;    window.addEventListener(&#x27;mousemove&#x27;, update)  &#125;)    onUnmounted(() =&gt; &#123;    window.removeEventListener(&#x27;mousemove&#x27;, update)  &#125;)    return &#123; x, y &#125;&#125;

&lt;!-- MouseTracker.vue --&gt;&lt;template&gt;  &lt;div&gt;    &lt;p&gt;鼠标位置: &#123;&#123; x &#125;&#125;, &#123;&#123; y &#125;&#125;&lt;/p&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; useMouse &#125; from &#x27;@/composables/useMouse&#x27;const &#123; x, y &#125; = useMouse()&lt;/script&gt;

实践练习2: 创建常用组合式函数集合
// composables/useCounter.jsimport &#123; ref, computed &#125; from &#x27;vue&#x27;export function useCounter(initialValue = 0) &#123;  const count = ref(initialValue)    const increment = () =&gt; count.value++  const decrement = () =&gt; count.value--  const reset = () =&gt; count.value = initialValue    const double = computed(() =&gt; count.value * 2)    return &#123;    count,    increment,    decrement,    reset,    double  &#125;&#125;

// composables/useLocalStorage.jsimport &#123; ref, watch &#125; from &#x27;vue&#x27;export function useLocalStorage(key, defaultValue) &#123;  // 从 localStorage 读取初始值  const value = ref(    JSON.parse(localStorage.getItem(key)) || defaultValue  )    // 监听变化并保存到 localStorage  watch(value, (newValue) =&gt; &#123;    localStorage.setItem(key, JSON.stringify(newValue))  &#125;, &#123; deep: true &#125;)    return value&#125;

// composables/useFetch.jsimport &#123; ref, toValue &#125; from &#x27;vue&#x27;export function useFetch(url) &#123;  const data = ref(null)  const error = ref(null)  const loading = ref(true)    const fetchData = async () =&gt; &#123;    loading.value = true    error.value = null        try &#123;      const response = await fetch(toValue(url))      if (!response.ok) throw new Error(&#x27;请求失败&#x27;)      data.value = await response.json()    &#125; catch (e) &#123;      error.value = e    &#125; finally &#123;      loading.value = false    &#125;  &#125;    // 立即执行  fetchData()    return &#123;    data,    error,    loading,    refetch: fetchData  &#125;&#125;

// composables/useDebounce.jsimport &#123; ref, watch &#125; from &#x27;vue&#x27;export function useDebounce(value, delay = 500) &#123;  const debouncedValue = ref(value.value)  let timeout    watch(value, (newValue) =&gt; &#123;    clearTimeout(timeout)    timeout = setTimeout(() =&gt; &#123;      debouncedValue.value = newValue    &#125;, delay)  &#125;)    return debouncedValue&#125;

// composables/useToggle.jsimport &#123; ref &#125; from &#x27;vue&#x27;export function useToggle(initialValue = false) &#123;  const value = ref(initialValue)    const toggle = () =&gt; &#123;    value.value = !value.value  &#125;    const setTrue = () =&gt; &#123;    value.value = true  &#125;    const setFalse = () =&gt; &#123;    value.value = false  &#125;    return &#123;    value,    toggle,    setTrue,    setFalse  &#125;&#125;

// composables/useClickOutside.jsimport &#123; onMounted, onUnmounted &#125; from &#x27;vue&#x27;export function useClickOutside(elementRef, callback) &#123;  const handleClick = (event) =&gt; &#123;    if (      elementRef.value &amp;&amp;      !elementRef.value.contains(event.target)    ) &#123;      callback(event)    &#125;  &#125;    onMounted(() =&gt; &#123;    document.addEventListener(&#x27;click&#x27;, handleClick)  &#125;)    onUnmounted(() =&gt; &#123;    document.removeEventListener(&#x27;click&#x27;, handleClick)  &#125;)&#125;


六、watch 和 watchEffect6.1 watch&lt;script setup&gt;import &#123; ref, watch &#125; from &#x27;vue&#x27;const count = ref(0)const name = ref(&#x27;张三&#x27;)// 监听单个 refwatch(count, (newValue, oldValue) =&gt; &#123;  console.log(`count 从 $&#123;oldValue&#125; 变为 $&#123;newValue&#125;`)&#125;)// 监听多个 refwatch([count, name], ([newCount, newName], [oldCount, oldName]) =&gt; &#123;  console.log(`count: $&#123;oldCount&#125; -&gt; $&#123;newCount&#125;`)  console.log(`name: $&#123;oldName&#125; -&gt; $&#123;newName&#125;`)&#125;)// 监听对象的某个属性const user = ref(&#123;  name: &#x27;张三&#x27;,  age: 25&#125;)watch(  () =&gt; user.value.age,  (newAge, oldAge) =&gt; &#123;    console.log(`age: $&#123;oldAge&#125; -&gt; $&#123;newAge&#125;`)  &#125;)// 监听 reactive 对象import &#123; reactive &#125; from &#x27;vue&#x27;const state = reactive(&#123;  count: 0,  name: &#x27;张三&#x27;&#125;)// 监听整个对象watch(  () =&gt; state,  (newState, oldState) =&gt; &#123;    console.log(&#x27;state changed&#x27;)  &#125;,  &#123; deep: true &#125;)// 监听特定属性watch(  () =&gt; state.count,  (newCount, oldCount) =&gt; &#123;    console.log(`count: $&#123;oldCount&#125; -&gt; $&#123;newCount&#125;`)  &#125;)// 选项watch(count, (newCount) =&gt; &#123;  console.log(&#x27;count changed:&#x27;, newCount)&#125;, &#123;  immediate: true, // 立即执行一次  deep: true,      // 深度监听  flush: &#x27;post&#x27;    // 在 DOM 更新后执行&#125;)// 停止监听const stop = watch(count, (newCount) =&gt; &#123;  console.log(&#x27;count:&#x27;, newCount)&#125;)// 调用 stop() 停止监听&lt;/script&gt;

6.2 watchEffect&lt;script setup&gt;import &#123; ref, watchEffect &#125; from &#x27;vue&#x27;const count = ref(0)const name = ref(&#x27;张三&#x27;)// 自动追踪依赖watchEffect(() =&gt; &#123;  console.log(`count: $&#123;count.value&#125;, name: $&#123;name.value&#125;`)&#125;)// 停止监听const stop = watchEffect(() =&gt; &#123;  console.log(count.value)&#125;)// 清理副作用watchEffect((onCleanup) =&gt; &#123;  const timer = setInterval(() =&gt; &#123;    console.log(&#x27;timer&#x27;)  &#125;, 1000)    onCleanup(() =&gt; &#123;    clearInterval(timer)  &#125;)&#125;)&lt;/script&gt;

6.3 watch vs watchEffect&lt;script setup&gt;import &#123; ref, watch, watchEffect &#125; from &#x27;vue&#x27;const count = ref(0)// watchEffect - 自动追踪依赖,立即执行watchEffect(() =&gt; &#123;  console.log(`count: $&#123;count.value&#125;`)&#125;)// watch - 显式指定依赖,惰性执行watch(count, (newCount) =&gt; &#123;  console.log(`count changed to: $&#123;newCount&#125;`)&#125;)// 使用场景// watchEffect: 当你需要自动追踪依赖时// watch: 当你需要访问旧值或精确控制依赖时&lt;/script&gt;

实践练习3: 创建一个搜索组件,使用 watch 实现防抖
&lt;template&gt;  &lt;div&gt;    &lt;input      v-model=&quot;searchText&quot;      placeholder=&quot;搜索...&quot;    /&gt;    &lt;div v-if=&quot;loading&quot;&gt;搜索中...&lt;/div&gt;    &lt;div v-else&gt;      &lt;p v-for=&quot;result in results&quot; :key=&quot;result.id&quot;&gt;        &#123;&#123; result.name &#125;&#125;      &lt;/p&gt;    &lt;/div&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref, watch &#125; from &#x27;vue&#x27;const searchText = ref(&#x27;&#x27;)const results = ref([])const loading = ref(false)let timeout = nullwatch(searchText, (newValue) =&gt; &#123;  // 清除之前的定时器  clearTimeout(timeout)    if (!newValue.trim()) &#123;    results.value = []    return  &#125;    // 设置新的定时器(防抖)  timeout = setTimeout(async () =&gt; &#123;    loading.value = true        try &#123;      const response = await fetch(`/api/search?q=$&#123;newValue&#125;`)      results.value = await response.json()    &#125; catch (error) &#123;      console.error(&#x27;搜索失败:&#x27;, error)    &#125; finally &#123;      loading.value = false    &#125;  &#125;, 500)&#125;)&lt;/script&gt;


七、模板引用7.1 使用 ref 获取 DOM 元素&lt;template&gt;  &lt;div&gt;    &lt;input ref=&quot;inputRef&quot; /&gt;    &lt;button @click=&quot;focusInput&quot;&gt;聚焦&lt;/button&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref, onMounted &#125; from &#x27;vue&#x27;const inputRef = ref(null)const focusInput = () =&gt; &#123;  inputRef.value.focus()&#125;onMounted(() =&gt; &#123;  inputRef.value.focus()&#125;)&lt;/script&gt;

7.2 组件引用&lt;template&gt;  &lt;div&gt;    &lt;ChildComponent ref=&quot;childRef&quot; /&gt;    &lt;button @click=&quot;callChildMethod&quot;&gt;调用子组件方法&lt;/button&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref &#125; from &#x27;vue&#x27;import ChildComponent from &#x27;./ChildComponent.vue&#x27;const childRef = ref(null)const callChildMethod = () =&gt; &#123;  childRef.value.someMethod()&#125;&lt;/script&gt;

&lt;!-- ChildComponent.vue --&gt;&lt;script setup&gt;const someMethod = () =&gt; &#123;  console.log(&#x27;子组件方法被调用&#x27;)&#125;// 暴露给父组件defineExpose(&#123;  someMethod&#125;)&lt;/script&gt;

7.3 v-for 中的 ref&lt;template&gt;  &lt;div&gt;    &lt;div      v-for=&quot;item in list&quot;      :key=&quot;item.id&quot;      :ref=&quot;(el) =&gt; setItemRef(el, item.id)&quot;    &gt;      &#123;&#123; item.name &#125;&#125;    &lt;/div&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref &#125; from &#x27;vue&#x27;const list = ref([  &#123; id: 1, name: &#x27;Item 1&#x27; &#125;,  &#123; id: 2, name: &#x27;Item 2&#x27; &#125;,  &#123; id: 3, name: &#x27;Item 3&#x27; &#125;])const itemRefs = ref(&#123;&#125;)const setItemRef = (el, id) =&gt; &#123;  if (el) &#123;    itemRefs.value[id] = el  &#125;&#125;&lt;/script&gt;


八、最佳实践8.1 组合式函数命名规范// ✅ 好的命名:use 前缀export function useMouse() &#123; &#125;export function useCounter() &#123; &#125;export function useFetch() &#123; &#125;// ❌ 不好的命名export function mouse() &#123; &#125;export function getCounter() &#123; &#125;export function createFetch() &#123; &#125;

8.2 组合式函数返回值// ✅ 返回响应式引用export function useCounter() &#123;  const count = ref(0)  const increment = () =&gt; count.value++    return &#123;    count,    increment  &#125;&#125;// ✅ 返回只读的响应式对象export function useMouse() &#123;  const x = ref(0)  const y = ref(0)    return &#123;    x,    y  &#125;&#125;// ✅ 返回函数用于操作export function useToggle() &#123;  const value = ref(false)    const toggle = () =&gt; value.value = !value.value    return &#123;    value,    toggle  &#125;&#125;

8.3 组合式函数的参数// ✅ 接受响应式值export function useFetch(url) &#123;  // url 可以是 ref 或 reactive 的值  // 使用 toValue 解包  const data = ref(null)    watchEffect(async () =&gt; &#123;    data.value = await fetch(toValue(url)).then(r =&gt; r.json())  &#125;)    return &#123; data &#125;&#125;// 使用const url = ref(&#x27;/api/users&#x27;)const &#123; data &#125; = useFetch(url)// 或者const &#123; data &#125; = useFetch(&#x27;/api/users&#x27;)

8.4 避免在组合式函数中直接修改 props&lt;script setup&gt;// ❌ 不要这样做export function useCounter(props) &#123;  const count = ref(props.initialValue)    const increment = () =&gt; &#123;    count.value++  &#125;    return &#123; count, increment &#125;&#125;// ✅ 应该这样做export function useCounter(initialValue) &#123;  const count = ref(initialValue)    const increment = () =&gt; &#123;    count.value++  &#125;    return &#123; count, increment &#125;&#125;// 使用const &#123; count, increment &#125; = useCounter(0)&lt;/script&gt;


九、实战案例9.1 用户状态管理// composables/useAuth.jsimport &#123; ref, computed &#125; from &#x27;vue&#x27;import &#123; useRouter &#125; from &#x27;vue-router&#x27;const user = ref(null)const token = ref(localStorage.getItem(&#x27;token&#x27;))const loading = ref(false)export function useAuth() &#123;  const router = useRouter()    const isLoggedIn = computed(() =&gt; !!user.value &amp;&amp; !!token.value)    const login = async (credentials) =&gt; &#123;    loading.value = true        try &#123;      const response = await fetch(&#x27;/api/login&#x27;, &#123;        method: &#x27;POST&#x27;,        headers: &#123; &#x27;Content-Type&#x27;: &#x27;application/json&#x27; &#125;,        body: JSON.stringify(credentials)      &#125;)            const data = await response.json()            user.value = data.user      token.value = data.token      localStorage.setItem(&#x27;token&#x27;, data.token)            return data    &#125; finally &#123;      loading.value = false    &#125;  &#125;    const logout = async () =&gt; &#123;    await fetch(&#x27;/api/logout&#x27;, &#123; method: &#x27;POST&#x27; &#125;)        user.value = null    token.value = null    localStorage.removeItem(&#x27;token&#x27;)        router.push(&#x27;/login&#x27;)  &#125;    const fetchUser = async () =&gt; &#123;    if (!token.value) return        try &#123;      const response = await fetch(&#x27;/api/user&#x27;, &#123;        headers: &#123; &#x27;Authorization&#x27;: `Bearer $&#123;token.value&#125;` &#125;      &#125;)            if (response.ok) &#123;        user.value = await response.json()      &#125;    &#125; catch (error) &#123;      console.error(&#x27;获取用户失败:&#x27;, error)    &#125;  &#125;    return &#123;    user,    token,    loading,    isLoggedIn,    login,    logout,    fetchUser  &#125;&#125;

9.2 分页组件// composables/usePagination.jsimport &#123; ref, computed &#125; from &#x27;vue&#x27;export function usePagination(fetchFn, pageSize = 10) &#123;  const items = ref([])  const currentPage = ref(1)  const totalItems = ref(0)  const totalPages = ref(0)  const loading = ref(false)  const error = ref(null)    const hasNextPage = computed(() =&gt; currentPage.value &lt; totalPages.value)  const hasPrevPage = computed(() =&gt; currentPage.value &gt; 1)    const fetchPage = async (page = 1) =&gt; &#123;    loading.value = true    error.value = null        try &#123;      const response = await fetchFn(&#123;        page,        pageSize      &#125;)            items.value = response.data      totalItems.value = response.total      totalPages.value = Math.ceil(response.total / pageSize)      currentPage.value = page    &#125; catch (e) &#123;      error.value = e    &#125; finally &#123;      loading.value = false    &#125;  &#125;    const nextPage = () =&gt; &#123;    if (hasNextPage.value) &#123;      fetchPage(currentPage.value + 1)    &#125;  &#125;    const prevPage = () =&gt; &#123;    if (hasPrevPage.value) &#123;      fetchPage(currentPage.value - 1)    &#125;  &#125;    const goToPage = (page) =&gt; &#123;    if (page &gt;= 1 &amp;&amp; page &lt;= totalPages.value) &#123;      fetchPage(page)    &#125;  &#125;    const refresh = () =&gt; &#123;    fetchPage(currentPage.value)  &#125;    // 初始加载  fetchPage(1)    return &#123;    items,    currentPage,    totalItems,    totalPages,    loading,    error,    hasNextPage,    hasPrevPage,    nextPage,    prevPage,    goToPage,    refresh  &#125;&#125;


总结Composition API 是 Vue 3 的核心特性,掌握以下关键点:

响应式系统: 理解 ref 和 reactive 的区别和使用场景
计算属性: 合理使用 computed 进行性能优化
生命周期: 在正确的钩子中执行正确的操作
组合式函数: 封装和复用有状态逻辑
watch&#x2F;watchEffect: 灵活监听和响应状态变化
最佳实践: 遵循命名和结构规范

通过 Composition API,可以编写出更清晰、更易维护的 Vue 应用。
