Vue.js 网络请求 Axios一、Axios 简介1.1 什么是 AxiosAxios 是一个基于 Promise 的 HTTP 客户端,可以用于浏览器和 Node.js。它具有以下特点:

支持 Promise API
拦截请求和响应
转换请求数据和响应数据
取消请求
自动转换 JSON 数据
客户端支持防御 XSRF

1.2 安装 Axiosnpm install axios# 或yarn add axios# 或pnpm add axios


二、Axios 基本配置2.1 创建 Axios 实例// utils/request.jsimport axios from &#x27;axios&#x27;// 创建 axios 实例const service = axios.create(&#123;  baseURL: process.env.VUE_APP_BASE_API || &#x27;http://localhost:3000/api&#x27;,  timeout: 10000, // 请求超时时间  headers: &#123;    &#x27;Content-Type&#x27;: &#x27;application/json;charset=UTF-8&#x27;  &#125;&#125;)export default service

2.2 配置项详解// 完整配置示例const instance = axios.create(&#123;  // 基础 URL  baseURL: &#x27;https://api.example.com&#x27;,    // 请求超时时间(毫秒)  timeout: 10000,    // 自定义请求头  headers: &#123;    &#x27;Content-Type&#x27;: &#x27;application/json&#x27;,    &#x27;Authorization&#x27;: &#x27;Bearer token&#x27;  &#125;,    // 响应数据格式  responseType: &#x27;json&#x27;, // &#x27;arraybuffer&#x27;, &#x27;blob&#x27;, &#x27;document&#x27;, &#x27;json&#x27;, &#x27;text&#x27;, &#x27;stream&#x27;    // 响应编码  responseEncoding: &#x27;utf8&#x27;,    // 是否携带 Cookie  withCredentials: false,    // 请求参数序列化  paramsSerializer: function(params) &#123;    return Qs.stringify(params, &#123; arrayFormat: &#x27;brackets&#x27; &#125;)  &#125;,    // 上传进度  onUploadProgress: function(progressEvent) &#123;    const percentCompleted = Math.round(      (progressEvent.loaded * 100) / progressEvent.total    )    console.log(`上传进度: $&#123;percentCompleted&#125;%`)  &#125;,    // 下载进度  onDownloadProgress: function(progressEvent) &#123;    const percentCompleted = Math.round(      (progressEvent.loaded * 100) / progressEvent.total    )    console.log(`下载进度: $&#123;percentCompleted&#125;%`)  &#125;&#125;)


三、请求拦截器3.1 请求拦截器// utils/request.jsimport axios from &#x27;axios&#x27;import &#123; useUserStore &#125; from &#x27;@/stores/user&#x27;const service = axios.create(&#123;  baseURL: process.env.VUE_APP_BASE_API,  timeout: 10000&#125;)// 请求拦截器service.interceptors.request.use(  config =&gt; &#123;    const userStore = useUserStore()        // 添加 token 到请求头    if (userStore.token) &#123;      config.headers[&#x27;Authorization&#x27;] = `Bearer $&#123;userStore.token&#125;`    &#125;        // 添加请求时间戳(防止缓存)    if (config.method === &#x27;get&#x27;) &#123;      config.params = &#123;        ...config.params,        _t: Date.now()      &#125;    &#125;        console.log(&#x27;Request:&#x27;, config)    return config  &#125;,  error =&gt; &#123;    console.error(&#x27;Request Error:&#x27;, error)    return Promise.reject(error)  &#125;)export default service

3.2 响应拦截器// utils/request.js// 响应拦截器service.interceptors.response.use(  response =&gt; &#123;    const res = response.data        // 根据业务状态码处理    if (res.code !== 200) &#123;      console.error(&#x27;Response Error:&#x27;, res.message || &#x27;Error&#x27;)            // 处理特定错误码      if (res.code === 401) &#123;        // Token 过期        const userStore = useUserStore()        userStore.logout()        location.reload()      &#125;            return Promise.reject(new Error(res.message || &#x27;Error&#x27;))    &#125;        return res  &#125;,  error =&gt; &#123;    console.error(&#x27;Response Error:&#x27;, error)        // 处理 HTTP 状态码错误    if (error.response) &#123;      const status = error.response.status            switch (status) &#123;        case 400:          error.message = &#x27;请求错误&#x27;          break        case 401:          error.message = &#x27;未授权,请登录&#x27;          // 跳转到登录页          router.push(&#x27;/login&#x27;)          break        case 403:          error.message = &#x27;拒绝访问&#x27;          break        case 404:          error.message = &#x27;请求地址不存在&#x27;          break        case 408:          error.message = &#x27;请求超时&#x27;          break        case 500:          error.message = &#x27;服务器内部错误&#x27;          break        case 501:          error.message = &#x27;服务未实现&#x27;          break        case 502:          error.message = &#x27;网关错误&#x27;          break        case 503:          error.message = &#x27;服务不可用&#x27;          break        case 504:          error.message = &#x27;网关超时&#x27;          break        case 505:          error.message = &#x27;HTTP版本不受支持&#x27;          break        default:          error.message = `连接错误 $&#123;status&#125;`      &#125;    &#125; else if (error.request) &#123;      error.message = &#x27;服务器未响应&#x27;    &#125; else &#123;      error.message = &#x27;请求配置错误&#x27;    &#125;        return Promise.reject(error)  &#125;)


四、API 模块化4.1 组织 API 文件src/  api/    index.js       # 统一导出    user.js        # 用户相关 API    product.js     # 商品相关 API    order.js       # 订单相关 API

4.2 封装 API 方法// api/user.jsimport request from &#x27;@/utils/request&#x27;// 用户登录export function login(data) &#123;  return request(&#123;    url: &#x27;/auth/login&#x27;,    method: &#x27;post&#x27;,    data  &#125;)&#125;// 用户注册export function register(data) &#123;  return request(&#123;    url: &#x27;/auth/register&#x27;,    method: &#x27;post&#x27;,    data  &#125;)&#125;// 获取用户信息export function getUserInfo() &#123;  return request(&#123;    url: &#x27;/user/info&#x27;,    method: &#x27;get&#x27;  &#125;)&#125;// 更新用户信息export function updateUserInfo(data) &#123;  return request(&#123;    url: &#x27;/user/info&#x27;,    method: &#x27;put&#x27;,    data  &#125;)&#125;// 上传头像export function uploadAvatar(file) &#123;  const formData = new FormData()  formData.append(&#x27;avatar&#x27;, file)    return request(&#123;    url: &#x27;/user/avatar&#x27;,    method: &#x27;post&#x27;,    data: formData,    headers: &#123;      &#x27;Content-Type&#x27;: &#x27;multipart/form-data&#x27;    &#125;  &#125;)&#125;

// api/product.jsimport request from &#x27;@/utils/request&#x27;// 获取商品列表export function getProducts(params) &#123;  return request(&#123;    url: &#x27;/products&#x27;,    method: &#x27;get&#x27;,    params  &#125;)&#125;// 获取商品详情export function getProductDetail(id) &#123;  return request(&#123;    url: `/products/$&#123;id&#125;`,    method: &#x27;get&#x27;  &#125;)&#125;// 搜索商品export function searchProducts(keyword) &#123;  return request(&#123;    url: &#x27;/products/search&#x27;,    method: &#x27;get&#x27;,    params: &#123; keyword &#125;  &#125;)&#125;// 获取商品分类export function getCategories() &#123;  return request(&#123;    url: &#x27;/products/categories&#x27;,    method: &#x27;get&#x27;  &#125;)&#125;

// api/index.jsexport * from &#x27;./user&#x27;export * from &#x27;./product&#x27;export * from &#x27;./order&#x27;


