实践练习1: 创建一个完整的 API 请求封装
// utils/request.jsimport axios from &#x27;axios&#x27;import &#123; ElMessage &#125; from &#x27;element-plus&#x27;import &#123; useUserStore &#125; from &#x27;@/stores/user&#x27;import router from &#x27;@/router&#x27;// 是否正在刷新 tokenlet isRefreshing = false// 重试请求队列let retryQueue = []// 创建 axios 实例const service = axios.create(&#123;  baseURL: import.meta.env.VITE_API_BASE_URL,  timeout: 30000,  headers: &#123;    &#x27;Content-Type&#x27;: &#x27;application/json;charset=UTF-8&#x27;  &#125;&#125;)// 请求拦截器service.interceptors.request.use(  config =&gt; &#123;    const userStore = useUserStore()        // 添加 token    if (userStore.token) &#123;      config.headers[&#x27;Authorization&#x27;] = `Bearer $&#123;userStore.token&#125;`    &#125;        // 添加设备信息    config.headers[&#x27;X-Device-Type&#x27;] = navigator.userAgent        return config  &#125;,  error =&gt; &#123;    console.error(&#x27;Request error:&#x27;, error)    return Promise.reject(error)  &#125;)// 响应拦截器service.interceptors.response.use(  response =&gt; &#123;    const res = response.data        // 二进制数据直接返回    if (response.config.responseType === &#x27;blob&#x27;) &#123;      return response    &#125;        // 业务错误处理    if (res.code &amp;&amp; res.code !== 200) &#123;      // Token 过期      if (res.code === 401) &#123;        return handleTokenExpired(response.config)      &#125;            // 其他错误      ElMessage.error(res.message || &#x27;请求失败&#x27;)      return Promise.reject(new Error(res.message || &#x27;请求失败&#x27;))    &#125;        return res  &#125;,  async error =&gt; &#123;    const &#123; response, config &#125; = error        if (!response) &#123;      ElMessage.error(&#x27;网络连接失败,请检查网络&#x27;)      return Promise.reject(error)    &#125;        const &#123; status &#125; = response        // Token 过期    if (status === 401) &#123;      return handleTokenExpired(config)    &#125;        // 其他 HTTP 错误    const errorMessage = getErrorMessage(status)    ElMessage.error(errorMessage)        return Promise.reject(error)  &#125;)// 处理 Token 过期async function handleTokenExpired(config) &#123;  const userStore = useUserStore()    // 如果正在刷新 token,将请求加入队列  if (isRefreshing) &#123;    return new Promise((resolve) =&gt; &#123;      retryQueue.push(() =&gt; &#123;        resolve(service(config))      &#125;)    &#125;)  &#125;    isRefreshing = true    try &#123;    // 刷新 token    const refreshToken = userStore.refreshToken    const response = await axios.post(&#x27;/auth/refresh&#x27;, &#123;      refreshToken    &#125;)        const &#123; token, refreshToken: newRefreshToken &#125; = response.data        // 更新 token    userStore.setToken(token, newRefreshToken)        // 重试队列中的请求    retryQueue.forEach(callback =&gt; callback())    retryQueue = []        // 重试当前请求    return service(config)  &#125; catch (error) &#123;    // 刷新失败,退出登录    userStore.logout()    router.push(&#x27;/login&#x27;)    return Promise.reject(error)  &#125; finally &#123;    isRefreshing = false  &#125;&#125;// 获取错误消息function getErrorMessage(status) &#123;  const messages = &#123;    400: &#x27;请求参数错误&#x27;,    401: &#x27;未授权,请重新登录&#x27;,    403: &#x27;拒绝访问&#x27;,    404: &#x27;请求资源不存在&#x27;,    405: &#x27;请求方法不允许&#x27;,    408: &#x27;请求超时&#x27;,    500: &#x27;服务器内部错误&#x27;,    502: &#x27;网关错误&#x27;,    503: &#x27;服务不可用&#x27;,    504: &#x27;网关超时&#x27;  &#125;    return messages[status] || `请求失败 ($&#123;status&#125;)`&#125;export default service


六、高级功能6.1 请求取消// utils/request.js// 存储所有请求const pendingRequests = new Map()// 生成请求 keyfunction generateRequestKey(config) &#123;  const &#123; method, url, params, data &#125; = config  return [method, url, JSON.stringify(params), JSON.stringify(data)].join(&#x27;&amp;&#x27;)&#125;// 添加请求到 Mapfunction addPendingRequest(config) &#123;  const requestKey = generateRequestKey(config)    if (pendingRequests.has(requestKey)) &#123;    // 取消之前的请求    const cancel = pendingRequests.get(requestKey)    cancel &amp;&amp; cancel(&#x27;取消重复请求&#x27;)  &#125;    config.cancelToken = new axios.CancelToken(cancel =&gt; &#123;    pendingRequests.set(requestKey, cancel)  &#125;)&#125;// 移除请求function removePendingRequest(config) &#123;  const requestKey = generateRequestKey(config)    if (pendingRequests.has(requestKey)) &#123;    pendingRequests.delete(requestKey)  &#125;&#125;// 请求拦截器service.interceptors.request.use(  config =&gt; &#123;    // 取消重复请求    addPendingRequest(config)        // ... 其他逻辑        return config  &#125;)// 响应拦截器service.interceptors.response.use(  response =&gt; &#123;    // 移除请求    removePendingRequest(response.config)        return response  &#125;,  error =&gt; &#123;    // 移除请求    if (error.config) &#123;      removePendingRequest(error.config)    &#125;        return Promise.reject(error)  &#125;)// 取消所有请求export function cancelAllRequests() &#123;  pendingRequests.forEach(cancel =&gt; &#123;    cancel &amp;&amp; cancel(&#x27;取消所有请求&#x27;)  &#125;)  pendingRequests.clear()&#125;

6.2 请求重试// utils/request.js// 重试配置const retryConfig = &#123;  retries: 3, // 重试次数  retryDelay: 1000, // 重试延迟  retryCondition: (error) =&gt; &#123;    // 重试条件    return !error.response || error.response.status &gt;= 500  &#125;&#125;// 响应拦截器service.interceptors.response.use(  response =&gt; response,  async error =&gt; &#123;    const &#123; config &#125; = error        // 如果没有配置重试,直接返回错误    if (!config || !config.retries) &#123;      return Promise.reject(error)    &#125;        // 设置重试次数    config.__retryCount = config.__retryCount || 0        // 检查是否可以重试    if (config.__retryCount &gt;= config.retries) &#123;      return Promise.reject(error)    &#125;        // 检查重试条件    if (!retryConfig.retryCondition(error)) &#123;      return Promise.reject(error)    &#125;        config.__retryCount += 1        // 延迟重试    await new Promise(resolve =&gt; &#123;      setTimeout(resolve, config.retryDelay || retryConfig.retryDelay)    &#125;)        // 重新发起请求    return service(config)  &#125;)

6.3 数据缓存// utils/cache.jsclass RequestCache &#123;  constructor(maxAge = 5 * 60 * 1000) &#123; // 默认缓存 5 分钟    this.cache = new Map()    this.maxAge = maxAge  &#125;    get(key) &#123;    const item = this.cache.get(key)        if (!item) return null        // 检查是否过期    if (Date.now() - item.timestamp &gt; this.maxAge) &#123;      this.cache.delete(key)      return null    &#125;        return item.data  &#125;    set(key, data) &#123;    this.cache.set(key, &#123;      data,      timestamp: Date.now()    &#125;)  &#125;    clear() &#123;    this.cache.clear()  &#125;    delete(key) &#123;    this.cache.delete(key)  &#125;&#125;export const requestCache = new RequestCache()

// api/product.jsimport request from &#x27;@/utils/request&#x27;import &#123; requestCache &#125; from &#x27;@/utils/cache&#x27;export function getProducts(params) &#123;  const cacheKey = `products_$&#123;JSON.stringify(params)&#125;`    // 检查缓存  const cachedData = requestCache.get(cacheKey)  if (cachedData) &#123;    return Promise.resolve(cachedData)  &#125;    return request(&#123;    url: &#x27;/products&#x27;,    method: &#x27;get&#x27;,    params  &#125;).then(response =&gt; &#123;    // 设置缓存    requestCache.set(cacheKey, response)    return response  &#125;)&#125;


七、文件上传下载7.1 文件上传// api/upload.jsimport request from &#x27;@/utils/request&#x27;// 上传单个文件export function uploadFile(file, onProgress) &#123;  const formData = new FormData()  formData.append(&#x27;file&#x27;, file)    return request(&#123;    url: &#x27;/upload&#x27;,    method: &#x27;post&#x27;,    data: formData,    headers: &#123;      &#x27;Content-Type&#x27;: &#x27;multipart/form-data&#x27;    &#125;,    onUploadProgress: (progressEvent) =&gt; &#123;      if (onProgress) &#123;        const percent = Math.round(          (progressEvent.loaded * 100) / progressEvent.total        )        onProgress(percent)      &#125;    &#125;  &#125;)&#125;// 上传多个文件export function uploadFiles(files, onProgress) &#123;  const formData = new FormData()    files.forEach(file =&gt; &#123;    formData.append(&#x27;files&#x27;, file)  &#125;)    return request(&#123;    url: &#x27;/upload/multiple&#x27;,    method: &#x27;post&#x27;,    data: formData,    headers: &#123;      &#x27;Content-Type&#x27;: &#x27;multipart/form-data&#x27;    &#125;,    onUploadProgress: (progressEvent) =&gt; &#123;      if (onProgress) &#123;        const percent = Math.round(          (progressEvent.loaded * 100) / progressEvent.total        )        onProgress(percent)      &#125;    &#125;  &#125;)&#125;// 分片上传export async function uploadChunk(file, chunkSize = 5 * 1024 * 1024) &#123;  const chunks = Math.ceil(file.size / chunkSize)  const fileId = Date.now()    for (let i = 0; i &lt; chunks; i++) &#123;    const start = i * chunkSize    const end = Math.min(file.size, start + chunkSize)    const chunk = file.slice(start, end)        const formData = new FormData()    formData.append(&#x27;file&#x27;, chunk)    formData.append(&#x27;fileId&#x27;, fileId)    formData.append(&#x27;chunkIndex&#x27;, i)    formData.append(&#x27;chunkTotal&#x27;, chunks)    formData.append(&#x27;fileName&#x27;, file.name)        await request(&#123;      url: &#x27;/upload/chunk&#x27;,      method: &#x27;post&#x27;,      data: formData,      headers: &#123;        &#x27;Content-Type&#x27;: &#x27;multipart/form-data&#x27;      &#125;    &#125;)  &#125;    // 合并分片  return request(&#123;    url: &#x27;/upload/merge&#x27;,    method: &#x27;post&#x27;,    data: &#123;      fileId,      fileName: file.name,      chunkTotal: chunks    &#125;  &#125;)&#125;

&lt;!-- FileUpload.vue --&gt;&lt;template&gt;  &lt;div class=&quot;file-upload&quot;&gt;    &lt;input      ref=&quot;fileInput&quot;      type=&quot;file&quot;      @change=&quot;handleFileChange&quot;      multiple    /&gt;        &lt;div v-if=&quot;uploadProgress &gt; 0&quot;&gt;      上传进度: &#123;&#123; uploadProgress &#125;&#125;%      &lt;div class=&quot;progress-bar&quot;&gt;        &lt;div           class=&quot;progress&quot;           :style=&quot;&#123; width: uploadProgress + &#x27;%&#x27; &#125;&quot;        &gt;&lt;/div&gt;      &lt;/div&gt;    &lt;/div&gt;        &lt;div v-if=&quot;uploadedFiles.length&quot;&gt;      已上传文件:      &lt;ul&gt;        &lt;li v-for=&quot;file in uploadedFiles&quot; :key=&quot;file.name&quot;&gt;          &#123;&#123; file.name &#125;&#125;        &lt;/li&gt;      &lt;/ul&gt;    &lt;/div&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script&gt;import &#123; ref &#125; from &#x27;vue&#x27;import &#123; uploadFiles &#125; from &#x27;@/api/upload&#x27;export default &#123;  setup() &#123;    const fileInput = ref(null)    const uploadProgress = ref(0)    const uploadedFiles = ref([])        const handleFileChange = async (event) =&gt; &#123;      const files = event.target.files            if (!files.length) return            uploadProgress.value = 0            try &#123;        const response = await uploadFiles(files, (percent) =&gt; &#123;          uploadProgress.value = percent        &#125;)                uploadedFiles.value = response.data                console.log(&#x27;上传成功&#x27;)      &#125; catch (error) &#123;        console.error(&#x27;上传失败:&#x27;, error)      &#125;    &#125;        return &#123;      fileInput,      uploadProgress,      uploadedFiles,      handleFileChange    &#125;  &#125;&#125;&lt;/script&gt;

7.2 文件下载// api/download.jsimport request from &#x27;@/utils/request&#x27;// 下载文件export function downloadFile(url, filename) &#123;  return request(&#123;    url,    method: &#x27;get&#x27;,    responseType: &#x27;blob&#x27;  &#125;).then(response =&gt; &#123;    const blob = new Blob([response.data])    const link = document.createElement(&#x27;a&#x27;)    link.href = URL.createObjectURL(blob)    link.download = filename    link.click()    URL.revokeObjectURL(link.href)  &#125;)&#125;// 下载文件(带进度)export function downloadFileWithProgress(url, filename, onProgress) &#123;  return request(&#123;    url,    method: &#x27;get&#x27;,    responseType: &#x27;blob&#x27;,    onDownloadProgress: (progressEvent) =&gt; &#123;      if (onProgress) &#123;        const percent = Math.round(          (progressEvent.loaded * 100) / progressEvent.total        )        onProgress(percent)      &#125;    &#125;  &#125;).then(response =&gt; &#123;    const blob = new Blob([response.data])    const link = document.createElement(&#x27;a&#x27;)    link.href = URL.createObjectURL(blob)    link.download = filename    link.click()    URL.revokeObjectURL(link.href)  &#125;)&#125;


八、最佳实践8.1 错误处理// utils/errorHandler.jsexport class ApiError extends Error &#123;  constructor(message, code, data) &#123;    super(message)    this.name = &#x27;ApiError&#x27;    this.code = code    this.data = data  &#125;&#125;export function handleApiError(error) &#123;  // 网络错误  if (!error.response) &#123;    return new ApiError(&#x27;网络连接失败&#x27;, &#x27;NETWORK_ERROR&#x27;)  &#125;    // 服务器错误  const &#123; status, data &#125; = error.response    switch (status) &#123;    case 400:      return new ApiError(&#x27;请求参数错误&#x27;, &#x27;BAD_REQUEST&#x27;, data)    case 401:      return new ApiError(&#x27;未授权访问&#x27;, &#x27;UNAUTHORIZED&#x27;, data)    case 403:      return new ApiError(&#x27;拒绝访问&#x27;, &#x27;FORBIDDEN&#x27;, data)    case 404:      return new ApiError(&#x27;资源不存在&#x27;, &#x27;NOT_FOUND&#x27;, data)    case 500:      return new ApiError(&#x27;服务器错误&#x27;, &#x27;SERVER_ERROR&#x27;, data)    default:      return new ApiError(&#x27;未知错误&#x27;, &#x27;UNKNOWN_ERROR&#x27;, data)  &#125;&#125;

8.2 Loading 管理// composables/useRequest.jsimport &#123; ref &#125; from &#x27;vue&#x27;export function useRequest(requestFn) &#123;  const loading = ref(false)  const error = ref(null)  const data = ref(null)    const execute = async (...args) =&gt; &#123;    loading.value = true    error.value = null        try &#123;      const result = await requestFn(...args)      data.value = result      return result    &#125; catch (e) &#123;      error.value = e      throw e    &#125; finally &#123;      loading.value = false    &#125;  &#125;    return &#123;    loading,    error,    data,    execute  &#125;&#125;

&lt;template&gt;  &lt;div&gt;    &lt;button @click=&quot;loadData&quot; :disabled=&quot;loading&quot;&gt;      &#123;&#123; loading ? &#x27;加载中...&#x27; : &#x27;加载数据&#x27; &#125;&#125;    &lt;/button&gt;        &lt;div v-if=&quot;error&quot;&gt;&#123;&#123; error.message &#125;&#125;&lt;/div&gt;    &lt;div v-else-if=&quot;data&quot;&gt;      &#123;&#123; data &#125;&#125;    &lt;/div&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script&gt;import &#123; useRequest &#125; from &#x27;@/composables/useRequest&#x27;import &#123; getProducts &#125; from &#x27;@/api/product&#x27;export default &#123;  setup() &#123;    const &#123; loading, error, data, execute &#125; = useRequest(getProducts)        const loadData = () =&gt; &#123;      execute(&#123; page: 1, limit: 10 &#125;)    &#125;        return &#123;      loading,      error,      data,      loadData    &#125;  &#125;&#125;&lt;/script&gt;


总结Axios 是 Vue.js 项目中最常用的 HTTP 客户端,掌握以下关键点:

拦截器: 统一处理请求和响应
错误处理: 友好的错误提示和处理
Token 刷新: 实现无感刷新 Token
请求取消: 避免重复请求
文件处理: 上传和下载文件
性能优化: 缓存、重试等策略

通过合理使用 Axios,可以构建出稳定、高效的网络请求层。
