Vue.js 状态管理 Pinia一、Pinia 简介1.1 什么是 PiniaPinia 是 Vue.js 的专属状态管理库,它允许你跨组件或页面共享状态。Pinia 于 2021 年成为 Vue.js 官方的状态管理库,取代了 Vuex。
Pinia 的优势:

支持 Vue 2 和 Vue 3
完整的 TypeScript 支持
轻量级,压缩后体积仅 1KB
移除了 mutations,简化了 API
支持 Vue DevTools
模块化设计,无需嵌套模块
支持服务端渲染

1.2 安装 Pinianpm install pinia# 或yarn add pinia# 或pnpm add pinia

1.3 基本配置// main.jsimport &#123; createApp &#125; from &#x27;vue&#x27;import &#123; createPinia &#125; from &#x27;pinia&#x27;import App from &#x27;./App.vue&#x27;const app = createApp(App)const pinia = createPinia()app.use(pinia)app.mount(&#x27;#app&#x27;)


二、定义 Store2.1 Option Store 风格// stores/counter.jsimport &#123; defineStore &#125; from &#x27;pinia&#x27;export const useCounterStore = defineStore(&#x27;counter&#x27;, &#123;  // state  state: () =&gt; (&#123;    count: 0,    name: &#x27;My Counter&#x27;  &#125;),    // getters  getters: &#123;    doubleCount: (state) =&gt; state.count * 2,        doubleCountPlusOne() &#123;      // 使用 this 访问其他 getter      return this.doubleCount + 1    &#125;  &#125;,    // actions  actions: &#123;    increment() &#123;      this.count++    &#125;,        decrement() &#123;      this.count--    &#125;,        async fetchCount() &#123;      const response = await fetch(&#x27;/api/count&#x27;)      const data = await response.json()      this.count = data.count    &#125;  &#125;&#125;)

2.2 Setup Store 风格// stores/counter.jsimport &#123; ref, computed &#125; from &#x27;vue&#x27;import &#123; defineStore &#125; from &#x27;pinia&#x27;export const useCounterStore = defineStore(&#x27;counter&#x27;, () =&gt; &#123;  // state  const count = ref(0)  const name = ref(&#x27;My Counter&#x27;)    // getters  const doubleCount = computed(() =&gt; count.value * 2)  const doubleCountPlusOne = computed(() =&gt; doubleCount.value + 1)    // actions  function increment() &#123;    count.value++  &#125;    function decrement() &#123;    count.value--  &#125;    async function fetchCount() &#123;    const response = await fetch(&#x27;/api/count&#x27;)    const data = await response.json()    count.value = data.count  &#125;    return &#123;    count,    name,    doubleCount,    doubleCountPlusOne,    increment,    decrement,    fetchCount  &#125;&#125;)

实践练习1: 创建一个用户状态管理 Store
// stores/user.jsimport &#123; defineStore &#125; from &#x27;pinia&#x27;export const useUserStore = defineStore(&#x27;user&#x27;, &#123;  state: () =&gt; (&#123;    user: null,    token: null,    isLoggedIn: false,    loading: false,    error: null  &#125;),    getters: &#123;    userId: (state) =&gt; state.user?.id,    userName: (state) =&gt; state.user?.name || &#x27;未登录&#x27;,    userAvatar: (state) =&gt; state.user?.avatar || &#x27;/default-avatar.png&#x27;,    isAdmin: (state) =&gt; state.user?.role === &#x27;admin&#x27;,    hasPermission: (state) =&gt; (permission) =&gt; &#123;      return state.user?.permissions?.includes(permission)    &#125;  &#125;,    actions: &#123;    async login(credentials) &#123;      this.loading = true      this.error = null            try &#123;        const response = await fetch(&#x27;/api/login&#x27;, &#123;          method: &#x27;POST&#x27;,          headers: &#123; &#x27;Content-Type&#x27;: &#x27;application/json&#x27; &#125;,          body: JSON.stringify(credentials)        &#125;)                if (!response.ok) throw new Error(&#x27;登录失败&#x27;)                const data = await response.json()        this.user = data.user        this.token = data.token        this.isLoggedIn = true                // 保存 token        localStorage.setItem(&#x27;token&#x27;, data.token)                return data      &#125; catch (error) &#123;        this.error = error.message        throw error      &#125; finally &#123;        this.loading = false      &#125;    &#125;,        async logout() &#123;      try &#123;        await fetch(&#x27;/api/logout&#x27;, &#123;          method: &#x27;POST&#x27;,          headers: &#123;            &#x27;Authorization&#x27;: `Bearer $&#123;this.token&#125;`          &#125;        &#125;)      &#125; finally &#123;        this.user = null        this.token = null        this.isLoggedIn = false        localStorage.removeItem(&#x27;token&#x27;)      &#125;    &#125;,        async fetchUser() &#123;      const token = localStorage.getItem(&#x27;token&#x27;)      if (!token) return            this.token = token            try &#123;        const response = await fetch(&#x27;/api/user&#x27;, &#123;          headers: &#123;            &#x27;Authorization&#x27;: `Bearer $&#123;token&#125;`          &#125;        &#125;)                if (response.ok) &#123;          const data = await response.json()          this.user = data.user          this.isLoggedIn = true        &#125;      &#125; catch (error) &#123;        console.error(&#x27;获取用户信息失败:&#x27;, error)      &#125;    &#125;,        updateProfile(profile) &#123;      if (this.user) &#123;        this.user = &#123; ...this.user, ...profile &#125;      &#125;    &#125;  &#125;&#125;)


