3.2 解构 Store&lt;script&gt;import &#123; storeToRefs &#125; from &#x27;pinia&#x27;import &#123; useCounterStore &#125; from &#x27;@/stores/counter&#x27;export default &#123;  setup() &#123;    const store = useCounterStore()        // ❌ 这不会工作,因为响应性会丢失    // const &#123; count, doubleCount &#125; = store        // ✅ 正确方式:使用 storeToRefs    const &#123; count, doubleCount &#125; = storeToRefs(store)        // Actions 不需要 storeToRefs    const &#123; increment, decrement &#125; = store        return &#123; count, doubleCount, increment, decrement &#125;  &#125;&#125;&lt;/script&gt;

