// stores/cart.jsimport &#123; defineStore &#125; from &#x27;pinia&#x27;export const useCartStore = defineStore(&#x27;cart&#x27;, &#123;  state: () =&gt; (&#123;    items: [],    checkoutPending: false  &#125;),    getters: &#123;    // 商品总数    itemsCount: (state) =&gt; state.items.reduce((sum, item) =&gt; sum + item.quantity, 0),        // 总价    totalPrice: (state) =&gt; &#123;      return state.items.reduce((total, item) =&gt; &#123;        return total + item.price * item.quantity      &#125;, 0)    &#125;,        // 格式化总价    formattedTotalPrice() &#123;      return `¥$&#123;this.totalPrice.toFixed(2)&#125;`    &#125;,        // 检查商品是否在购物车中    hasItem: (state) =&gt; (productId) =&gt; &#123;      return state.items.some(item =&gt; item.productId === productId)    &#125;,        // 获取商品数量    getItemQuantity: (state) =&gt; (productId) =&gt; &#123;      const item = state.items.find(item =&gt; item.productId === productId)      return item ? item.quantity : 0    &#125;  &#125;,    actions: &#123;    addItem(product, quantity = 1) &#123;      const existingItem = this.items.find(item =&gt; item.productId === product.id)            if (existingItem) &#123;        existingItem.quantity += quantity      &#125; else &#123;        this.items.push(&#123;          productId: product.id,          name: product.name,          price: product.price,          image: product.image,          quantity        &#125;)      &#125;    &#125;,        removeItem(productId) &#123;      const index = this.items.findIndex(item =&gt; item.productId === productId)      if (index &gt; -1) &#123;        this.items.splice(index, 1)      &#125;    &#125;,        updateQuantity(productId, quantity) &#123;      const item = this.items.find(item =&gt; item.productId === productId)      if (item) &#123;        if (quantity &lt;= 0) &#123;          this.removeItem(productId)        &#125; else &#123;          item.quantity = quantity        &#125;      &#125;    &#125;,        clearCart() &#123;      this.items = []    &#125;,        async checkout(shippingInfo) &#123;      this.checkoutPending = true            try &#123;        const response = await fetch(&#x27;/api/orders&#x27;, &#123;          method: &#x27;POST&#x27;,          headers: &#123; &#x27;Content-Type&#x27;: &#x27;application/json&#x27; &#125;,          body: JSON.stringify(&#123;            items: this.items,            shipping: shippingInfo          &#125;)        &#125;)                if (!response.ok) throw new Error(&#x27;Checkout failed&#x27;)                const order = await response.json()        this.clearCart()                return order      &#125; finally &#123;        this.checkoutPending = false      &#125;    &#125;  &#125;&#125;)

&lt;!-- Cart.vue --&gt;&lt;template&gt;  &lt;div class=&quot;cart&quot;&gt;    &lt;h2&gt;购物车&lt;/h2&gt;        &lt;div v-if=&quot;cart.itemsCount === 0&quot; class=&quot;empty&quot;&gt;      购物车是空的    &lt;/div&gt;        &lt;div v-else class=&quot;cart-items&quot;&gt;      &lt;div v-for=&quot;item in cart.items&quot; :key=&quot;item.productId&quot; class=&quot;cart-item&quot;&gt;        &lt;img :src=&quot;item.image&quot; :alt=&quot;item.name&quot; /&gt;        &lt;div class=&quot;item-info&quot;&gt;          &lt;h3&gt;&#123;&#123; item.name &#125;&#125;&lt;/h3&gt;          &lt;p class=&quot;price&quot;&gt;¥&#123;&#123; item.price &#125;&#125;&lt;/p&gt;        &lt;/div&gt;        &lt;div class=&quot;quantity-control&quot;&gt;          &lt;button @click=&quot;cart.updateQuantity(item.productId, item.quantity - 1)&quot;&gt;-&lt;/button&gt;          &lt;span&gt;&#123;&#123; item.quantity &#125;&#125;&lt;/span&gt;          &lt;button @click=&quot;cart.updateQuantity(item.productId, item.quantity + 1)&quot;&gt;+&lt;/button&gt;        &lt;/div&gt;        &lt;button @click=&quot;cart.removeItem(item.productId)&quot; class=&quot;remove-btn&quot;&gt;删除&lt;/button&gt;      &lt;/div&gt;    &lt;/div&gt;        &lt;div class=&quot;cart-summary&quot; v-if=&quot;cart.itemsCount &gt; 0&quot;&gt;      &lt;p&gt;商品总数: &#123;&#123; cart.itemsCount &#125;&#125;&lt;/p&gt;      &lt;p class=&quot;total&quot;&gt;总价: &#123;&#123; cart.formattedTotalPrice &#125;&#125;&lt;/p&gt;      &lt;button @click=&quot;checkout&quot; :disabled=&quot;cart.checkoutPending&quot;&gt;        结算      &lt;/button&gt;    &lt;/div&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script&gt;import &#123; useCartStore &#125; from &#x27;@/stores/cart&#x27;export default &#123;  setup() &#123;    const cart = useCartStore()        const checkout = async () =&gt; &#123;      try &#123;        const order = await cart.checkout(&#123;          address: &#x27;详细地址&#x27;,          phone: &#x27;13800138000&#x27;        &#125;)        console.log(&#x27;订单创建成功:&#x27;, order)      &#125; catch (error) &#123;        console.error(&#x27;结算失败:&#x27;, error)      &#125;    &#125;        return &#123; cart, checkout &#125;  &#125;&#125;&lt;/script&gt;


四、组合式函数4.1 在 Store 中使用其他 Store// stores/user.jsimport &#123; defineStore &#125; from &#x27;pinia&#x27;import &#123; useCartStore &#125; from &#x27;./cart&#x27;export const useUserStore = defineStore(&#x27;user&#x27;, &#123;  state: () =&gt; (&#123;    user: null,    isLoggedIn: false  &#125;),    actions: &#123;    async logout() &#123;      const cartStore = useCartStore()            // 清除购物车      cartStore.clearCart()            // 退出登录      await fetch(&#x27;/api/logout&#x27;, &#123; method: &#x27;POST&#x27; &#125;)            this.user = null      this.isLoggedIn = false    &#125;  &#125;&#125;)

4.2 使用组合式函数// stores/composables/useCartCalculations.jsimport &#123; computed &#125; from &#x27;vue&#x27;import &#123; useCartStore &#125; from &#x27;@/stores/cart&#x27;import &#123; useUserStore &#125; from &#x27;@/stores/user&#x27;export function useCartCalculations() &#123;  const cartStore = useCartStore()  const userStore = useUserStore()    const discount = computed(() =&gt; &#123;    if (!userStore.user) return 0        // VIP 用户 10% 折扣    if (userStore.user.level === &#x27;vip&#x27;) &#123;      return cartStore.totalPrice * 0.1    &#125;        return 0  &#125;)    const finalPrice = computed(() =&gt; &#123;    return cartStore.totalPrice - discount.value  &#125;)    return &#123;    discount,    finalPrice  &#125;&#125;


五、State 持久化5.1 手动持久化// stores/user.jsimport &#123; defineStore &#125; from &#x27;pinia&#x27;export const useUserStore = defineStore(&#x27;user&#x27;, &#123;  state: () =&gt; (&#123;    user: JSON.parse(localStorage.getItem(&#x27;user&#x27;) || &#x27;null&#x27;),    token: localStorage.getItem(&#x27;token&#x27;) || null  &#125;),    actions: &#123;    login(userData, token) &#123;      this.user = userData      this.token = token            // 持久化到 localStorage      localStorage.setItem(&#x27;user&#x27;, JSON.stringify(userData))      localStorage.setItem(&#x27;token&#x27;, token)    &#125;,        logout() &#123;      this.user = null      this.token = null            // 清除 localStorage      localStorage.removeItem(&#x27;user&#x27;)      localStorage.removeItem(&#x27;token&#x27;)    &#125;  &#125;&#125;)

