六、插件系统6.1 创建 Pinia 插件// plugins/pinia/logger.jsexport function PiniaLogger(&#123; store &#125;) &#123;  // 监听所有状态变化  store.$onAction((&#123; name, args, after, onError &#125;) =&gt; &#123;    const startTime = Date.now()    console.log(`[Pinia] Action $&#123;name&#125; started with args:`, args)        after((result) =&gt; &#123;      console.log(`[Pinia] Action $&#123;name&#125; finished in $&#123;Date.now() - startTime&#125;ms`)      console.log(&#x27;Result:&#x27;, result)    &#125;)        onError((error) =&gt; &#123;      console.error(`[Pinia] Action $&#123;name&#125; failed:`, error)    &#125;)  &#125;)    // 监听状态变化  store.$subscribe((mutation, state) =&gt; &#123;    console.log(&#x27;[Pinia] State changed:&#x27;, mutation.type)    console.log(&#x27;New state:&#x27;, state)  &#125;)&#125;

