七、TypeScript 支持7.1 定义类型化的 Store// stores/user.tsimport &#123; defineStore &#125; from &#x27;pinia&#x27;interface User &#123;  id: number  name: string  email: string  role: &#x27;admin&#x27; | &#x27;user&#x27;  permissions: string[]&#125;interface UserState &#123;  user: User | null  token: string | null  isLoggedIn: boolean&#125;export const useUserStore = defineStore(&#x27;user&#x27;, &#123;  state: (): UserState =&gt; (&#123;    user: null,    token: null,    isLoggedIn: false  &#125;),    getters: &#123;    userId: (state) =&gt; state.user?.id,    userName: (state) =&gt; state.user?.name || &#x27;未登录&#x27;,    isAdmin: (state) =&gt; state.user?.role === &#x27;admin&#x27;,        hasPermission: (state) =&gt; &#123;      return (permission: string): boolean =&gt; &#123;        return state.user?.permissions.includes(permission) ?? false      &#125;    &#125;  &#125;,    actions: &#123;    async login(credentials: &#123; email: string; password: string &#125;) &#123;      const response = await fetch(&#x27;/api/login&#x27;, &#123;        method: &#x27;POST&#x27;,        headers: &#123; &#x27;Content-Type&#x27;: &#x27;application/json&#x27; &#125;,        body: JSON.stringify(credentials)      &#125;)            const data = await response.json()      this.user = data.user      this.token = data.token      this.isLoggedIn = true    &#125;,        logout() &#123;      this.user = null      this.token = null      this.isLoggedIn = false    &#125;  &#125;&#125;)

