实践练习3: 创建一个待办事项应用 Store
// stores/todos.jsimport &#123; defineStore &#125; from &#x27;pinia&#x27;import &#123; ref, computed &#125; from &#x27;vue&#x27;export const useTodosStore = defineStore(&#x27;todos&#x27;, () =&gt; &#123;  // State  const todos = ref([])  const filter = ref(&#x27;all&#x27;) // all, active, completed  const loading = ref(false)    // Getters  const filteredTodos = computed(() =&gt; &#123;    switch (filter.value) &#123;      case &#x27;active&#x27;:        return todos.value.filter(todo =&gt; !todo.completed)      case &#x27;completed&#x27;:        return todos.value.filter(todo =&gt; todo.completed)      default:        return todos.value    &#125;  &#125;)    const totalTodos = computed(() =&gt; todos.value.length)  const activeTodos = computed(() =&gt; todos.value.filter(t =&gt; !t.completed).length)  const completedTodos = computed(() =&gt; todos.value.filter(t =&gt; t.completed).length)    // Actions  function addTodo(title) &#123;    const todo = &#123;      id: Date.now(),      title,      completed: false,      createdAt: new Date().toISOString()    &#125;    todos.value.unshift(todo)    saveToStorage()  &#125;    function removeTodo(id) &#123;    const index = todos.value.findIndex(t =&gt; t.id === id)    if (index &gt; -1) &#123;      todos.value.splice(index, 1)      saveToStorage()    &#125;  &#125;    function toggleTodo(id) &#123;    const todo = todos.value.find(t =&gt; t.id === id)    if (todo) &#123;      todo.completed = !todo.completed      saveToStorage()    &#125;  &#125;    function updateTodoTitle(id, title) &#123;    const todo = todos.value.find(t =&gt; t.id === id)    if (todo) &#123;      todo.title = title      saveToStorage()    &#125;  &#125;    function clearCompleted() &#123;    todos.value = todos.value.filter(t =&gt; !t.completed)    saveToStorage()  &#125;    function setFilter(newFilter) &#123;    filter.value = newFilter  &#125;    function saveToStorage() &#123;    localStorage.setItem(&#x27;todos&#x27;, JSON.stringify(todos.value))  &#125;    function loadFromStorage() &#123;    const saved = localStorage.getItem(&#x27;todos&#x27;)    if (saved) &#123;      todos.value = JSON.parse(saved)    &#125;  &#125;    // 初始化时加载  loadFromStorage()    return &#123;    // State    todos,    filter,    loading,        // Getters    filteredTodos,    totalTodos,    activeTodos,    completedTodos,        // Actions    addTodo,    removeTodo,    toggleTodo,    updateTodoTitle,    clearCompleted,    setFilter,    loadFromStorage  &#125;&#125;)

&lt;!-- TodoApp.vue --&gt;&lt;template&gt;  &lt;div class=&quot;todo-app&quot;&gt;    &lt;h1&gt;待办事项&lt;/h1&gt;        &lt;!-- 添加待办 --&gt;    &lt;div class=&quot;add-todo&quot;&gt;      &lt;input        v-model=&quot;newTodo&quot;        @keyup.enter=&quot;addTodo&quot;        placeholder=&quot;添加待办事项...&quot;      /&gt;      &lt;button @click=&quot;addTodo&quot;&gt;添加&lt;/button&gt;    &lt;/div&gt;        &lt;!-- 过滤器 --&gt;    &lt;div class=&quot;filters&quot;&gt;      &lt;button        :class=&quot;&#123; active: filter === &#x27;all&#x27; &#125;&quot;        @click=&quot;setFilter(&#x27;all&#x27;)&quot;      &gt;        全部 (&#123;&#123; totalTodos &#125;&#125;)      &lt;/button&gt;      &lt;button        :class=&quot;&#123; active: filter === &#x27;active&#x27; &#125;&quot;        @click=&quot;setFilter(&#x27;active&#x27;)&quot;      &gt;        待完成 (&#123;&#123; activeTodos &#125;&#125;)      &lt;/button&gt;      &lt;button        :class=&quot;&#123; active: filter === &#x27;completed&#x27; &#125;&quot;        @click=&quot;setFilter(&#x27;completed&#x27;)&quot;      &gt;        已完成 (&#123;&#123; completedTodos &#125;&#125;)      &lt;/button&gt;    &lt;/div&gt;        &lt;!-- 待办列表 --&gt;    &lt;ul class=&quot;todo-list&quot;&gt;      &lt;li        v-for=&quot;todo in filteredTodos&quot;        :key=&quot;todo.id&quot;        :class=&quot;&#123; completed: todo.completed &#125;&quot;      &gt;        &lt;input          type=&quot;checkbox&quot;          :checked=&quot;todo.completed&quot;          @change=&quot;toggleTodo(todo.id)&quot;        /&gt;        &lt;span&gt;&#123;&#123; todo.title &#125;&#125;&lt;/span&gt;        &lt;button @click=&quot;removeTodo(todo.id)&quot;&gt;删除&lt;/button&gt;      &lt;/li&gt;    &lt;/ul&gt;        &lt;!-- 清除已完成 --&gt;    &lt;button      v-if=&quot;completedTodos &gt; 0&quot;      @click=&quot;clearCompleted&quot;      class=&quot;clear-completed&quot;    &gt;      清除已完成 (&#123;&#123; completedTodos &#125;&#125;)    &lt;/button&gt;  &lt;/div&gt;&lt;/template&gt;&lt;script setup&gt;import &#123; ref &#125; from &#x27;vue&#x27;import &#123; useTodosStore &#125; from &#x27;@/stores/todos&#x27;import &#123; storeToRefs &#125; from &#x27;pinia&#x27;const todosStore = useTodosStore()const &#123; filteredTodos, totalTodos, activeTodos, completedTodos, filter &#125; = storeToRefs(todosStore)const &#123; addTodo: addTodoAction, removeTodo, toggleTodo, clearCompleted, setFilter &#125; = todosStoreconst newTodo = ref(&#x27;&#x27;)function addTodo() &#123;  if (newTodo.value.trim()) &#123;    addTodoAction(newTodo.value.trim())    newTodo.value = &#x27;&#x27;  &#125;&#125;&lt;/script&gt;&lt;style scoped&gt;.todo-app &#123;  max-width: 600px;  margin: 0 auto;  padding: 20px;&#125;.todo-list li &#123;  display: flex;  align-items: center;  gap: 10px;  padding: 10px;  border-bottom: 1px solid #eee;&#125;.todo-list li.completed span &#123;  text-decoration: line-through;  color: #999;&#125;.filters &#123;  margin: 20px 0;  display: flex;  gap: 10px;&#125;.filters button.active &#123;  background: #1890ff;  color: white;&#125;&lt;/style&gt;


总结Pinia 是 Vue.js 的现代状态管理解决方案,主要特点:

简单直观: API 简洁,易于理解和使用
类型安全: 完整的 TypeScript 支持
模块化: 每个 Store 独立,无需嵌套
DevTools: 集成 Vue DevTools,调试方便
轻量级: 体积小,性能优秀

通过 Pinia,可以有效管理应用的复杂状态,提高代码的可维护性。
